// A chosen item the estimate does not calculate: the page it is chosen
// on, its topic there in the interview map, the form lines refused, the issue
// that refuses it by name and the name the review gives it. Each item has one owner that declares this
// once: RareSituation for the less-common income and itemized deduction
// pages, and the payload-less items of the More adjustments, More credits
// and Other taxes page enums.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct Refusal {
    pub(crate) section: crate::TaxSection,
    #[cfg(test)]
    pub(crate) topic: &'static str,
    pub(crate) topic_key: &'static str,
    #[cfg(test)]
    pub(crate) lines: &'static str,
    pub(crate) issue_key: &'static str,
    pub(crate) name_key: &'static str,
}

impl Refusal {
    #[cfg_attr(not(test), allow(unused_variables))]
    fn new(
        section: crate::TaxSection,
        (topic, topic_key): (&'static str, &'static str),
        (lines, issue_key, name_key): (&'static str, &'static str, &'static str),
    ) -> Self {
        Self {
            section,
            #[cfg(test)]
            topic,
            topic_key,
            #[cfg(test)]
            lines,
            issue_key,
            name_key,
        }
    }
}

impl RareSituation {
    pub(crate) fn refused(self) -> Refusal {
        let (section, topic) = self.destination_info();
        Refusal::new(section, topic, self.refusal_info())
    }
}

impl crate::MoreAdjustment {
    // The payload-less items, which the estimate refuses by name.
    pub(crate) fn refused(&self) -> Option<Refusal> {
        let (topic, refusal) = match self {
            Self::OtherAdjustments => (
                (crate::fixture_english!("Other adjustments"), "TOPIC_OTHER_ADJUSTMENTS"),
                (
                    crate::fixture_english!(
                        "Other adjustments to income, including section 501(c)(18)(D) pension contributions (Schedule 1 lines 24a–24z)"
                    ),
                    "ISSUE_SITUATION_OTHER_ADJUSTMENTS",
                    "SITUATION_NAME_OTHER_ADJUSTMENTS",
                ),
            ),
            _ => return None,
        };
        Some(Refusal::new(crate::TaxSection::MoreAdjustments, topic, refusal))
    }
}

impl crate::MoreCredit {
    // The payload-less items, which the estimate refuses by name.
    pub(crate) fn refused(&self) -> Option<Refusal> {
        None
    }
}

impl crate::OtherTax {
    // The payload-less items, which the estimate refuses by name.
    pub(crate) fn refused(&self) -> Option<Refusal> {
        let (topic, refusal) = match self {
            Self::AlternativeMinimumTax => (
                (
                    crate::fixture_english!("Alternative minimum tax items"),
                    "TOPIC_ALTERNATIVE_MINIMUM_TAX_ITEMS",
                ),
                (
                    crate::fixture_english!(
                        "Alternative minimum tax adjustments and preferences (Form 6251)"
                    ),
                    "ISSUE_SITUATION_ALTERNATIVE_MINIMUM_TAX",
                    "SITUATION_NAME_ALTERNATIVE_MINIMUM_TAX",
                ),
            ),
            Self::HousingCreditRecapture => (
                (
                    crate::fixture_english!("Credit recapture and look-back interest"),
                    "TOPIC_CREDIT_RECAPTURE_AND_LOOK_BACK_INTEREST",
                ),
                (
                    crate::fixture_english!(
                        "Schedule 2 line 9 (Form 8611 recapture) and line 13n (Forms 8697/8866 look-back interest)"
                    ),
                    "ISSUE_SITUATION_HOUSING_CREDIT_RECAPTURE",
                    "SITUATION_NAME_HOUSING_CREDIT_RECAPTURE",
                ),
            ),
            Self::Section965 => (
                (
                    crate::fixture_english!("Deferred section 965 tax"),
                    "TOPIC_DEFERRED_SECTION_965_TAX",
                ),
                (
                    crate::fixture_english!(
                        "Schedule 3 line 13d (deferred section 965 tax liability)"
                    ),
                    "ISSUE_SITUATION_SECTION965",
                    "SITUATION_NAME_SECTION965",
                ),
            ),
            Self::OtherAdditionalTaxes { kind } => {
                let (topic, topic_key, lines, issue_key, name_key) = kind.refusal_info();
                return Some(Refusal::new(
                    crate::TaxSection::OtherTaxes,
                    (topic, topic_key),
                    (lines, issue_key, name_key),
                ));
            }
            _ => return None,
        };
        Some(Refusal::new(crate::TaxSection::OtherTaxes, topic, refusal))
    }
}

impl FederalDraft {
    // Every chosen item the estimate refuses, page by page in interview
    // order.
    pub(crate) fn refusals(&self) -> impl Iterator<Item = Refusal> + '_ {
        let situations = |section| {
            self.situations.iter().map(|s| s.refused()).filter(move |r| r.section == section)
        };
        situations(crate::TaxSection::Wages)
            .chain(situations(crate::TaxSection::MoreIncome))
            .chain(self.adjustment_refusals.iter().filter_map(crate::MoreAdjustment::refused))
            .chain(situations(crate::TaxSection::MoreItemized))
            .chain(self.credit_refusals.iter().filter_map(crate::MoreCreditRefusal::refused))
            .chain(self.tax_refusals.iter().filter_map(crate::OtherTaxRefusal::refused))
    }
}

// Refuse every chosen item by name, under the page it is chosen on.
pub(crate) fn refuse_situations(d: &FederalDraft, r: &mut FederalResult) {
    for refusal in d.refusals() {
        crate::issue_localized!(
            r,
            &crate::IssueContext::Section(refusal.section),
            crate::interview::section_name(refusal.section),
            refusal.issue_key,
            &alloc::format!("{} is not calculated yet.", refusal.lines),
        );
    }
}

// The checklist's whole-return answers (gate fixes batch A): the two
// returns outside the App's scope, with the issue and the name the review
// gives them (a refusal of the whole return, decision rule "Answers and
// unknowns").
pub(crate) const WHOLE_RETURN_REFUSALS: [(u32, &str, &str); 2] = [
    (
        crate::WholeReturnTopics::DUAL_STATUS.0,
        "ISSUE_SITUATION_DUAL_STATUS",
        "SITUATION_NAME_DUAL_STATUS",
    ),
    (
        crate::WholeReturnTopics::COMMUNITY_PROPERTY.0,
        "ISSUE_SITUATION_COMMUNITY_PROPERTY",
        "SITUATION_NAME_COMMUNITY_PROPERTY",
    ),
];
// The whole-return answers on the estimate. A dual-status or territory
// return and community property with a registered domestic partner are
// refused by name. The nonresident spouse choice (section 6013(g) or (h))
// is an ordinary joint return of both spouses' worldwide income with an
// attached statement, and innocent spouse relief is a separate Form 8857
// request that leaves this joint return's tax unchanged: each is a notice
// from the checklist. The injured spouse item opens Form 8379's page
// (T3-8379), which never changes the joint return's tax either.
pub(crate) fn whole_return(d: &FederalDraft, r: &mut FederalResult) {
    let ticks = d.checklist.whole_return;
    let checklist = crate::IssueContext::Section(crate::TaxSection::Checklist);
    for (bit, key, _) in WHOLE_RETURN_REFUSALS {
        if ticks & bit != 0 {
            let message = crate::Message::new(key, alloc::vec![]);
            issue_message(
                r,
                &checklist,
                #[cfg(test)]
                crate::interview::section_name(crate::TaxSection::Checklist),
                #[cfg(test)]
                message.english(),
                message,
            );
        }
    }
    for (bit, key) in [
        (
            crate::WholeReturnTopics::NONRESIDENT_SPOUSE.0,
            "NOTE_NONRESIDENT_SPOUSE_TREATED_AS_A_RESIDENT",
        ),
        (
            crate::WholeReturnTopics::INNOCENT_SPOUSE.0,
            "NOTE_INNOCENT_SPOUSE_RELIEF_IS_A_SEPARATE_REQUEST",
        ),
        (crate::WholeReturnTopics::NIIT_JOINT_ELECTION.0, "NOTE_NIIT_NONRESIDENT_SPOUSE_ELECTED"),
    ] {
        if ticks & bit != 0 {
            note_once_scoped(r, crate::Message::new(key, alloc::vec![]), checklist.clone());
        }
    }
}

// The W-2 box 12 codes the Wages page (unit M3-P2) collects but this App does
// not yet calculate an effect from: each is stored on `FederalWage.other_box12`
// (never dropped) and refused by name here, the same "stored, not rejected"
// pattern as every other unsupported situation. Codes D/E/F/G/S/W/AA/BB/EE are
// stored and not refused: their 401(k)/403(b)/457(b)/SIMPLE/Roth deferrals are
// already inside box 1/3/5 wages (codes D, E, F, S, AA and BB above the annual
// limit add the excess to line 1h: elective_deferrals.rs), and the box W HSA
// employer contribution awaits the HSA topic (M3-P7).
fn w2_box12_refusal(code: W2Code) -> Option<(&'static str, &'static str)> {
    Some(match code {
        W2Code::H => (
            "ISSUE_W2_BOX12_H_UNSUPPORTED",
            "W-2 box 12 code H (section 501(c)(18)(D) plan contributions, Schedule 1 line 24f) is not yet connected from this page.",
        ),
        W2Code::Z => (
            "ISSUE_W2_BOX12_Z_UNSUPPORTED",
            "W-2 box 12 code Z (section 409A deferred compensation income, additional tax) is not yet supported.",
        ),
        // A/B/M/N/TP/TT have their own stored fields (never in other_box12); P's effect
        // is calculated (Form 3903 line 4).
        W2Code::A
        | W2Code::B
        | W2Code::M
        | W2Code::N
        | W2Code::K
        | W2Code::P
        | W2Code::T
        | W2Code::TP
        | W2Code::TT
        | W2Code::D
        | W2Code::E
        | W2Code::F
        | W2Code::G
        | W2Code::S
        | W2Code::L
        | W2Code::W
        | W2Code::R
        | W2Code::AA
        | W2Code::BB
        | W2Code::EE
        | W2Code::FF
        | W2Code::Q
        | W2Code::II
        | W2Code::TA => return None,
    })
}
use crate::kernel::lines::{form_line, line, line_cents, push_line};
// The printed line of a "line<ref>_<name>" expense suffix ("line24b_meals"
// is line 24b), shared by the Schedule C and Schedule E expense categories.
pub(crate) fn printed_line(suffix: &str) -> &str {
    let rest = suffix.strip_prefix("line").unwrap_or(suffix);
    rest.split_once('_').map_or(rest, |(line, _)| line)
}
// A Schedule C line of an ordinary business; a farm reports on Schedule F
// and a professional gambler's capped expenses have no per-line split here.
fn schedule_c_line(v: &crate::FederalBusiness, line: &str) -> Option<FormLine> {
    matches!(v.activity, crate::BusinessActivity::Ordinary { .. })
        .then(|| FormLine::new(TaxForm::ScheduleC, line))
}
// One business's Schedule C summary lines, from the same amounts the return
// adds to business income: line 31 is receipts less every expense (cost of
// goods sold and the home office included); 29 adds the home office back, 28
// is the gross income left after 29. A professional gambler's Schedule C
// shows only line 31; a farm has none (Schedule F).
// Forward the same selected allocation and invocation-only HOME facts.
#[allow(clippy::too_many_arguments)]
fn schedule_c_lines(
    d: &FederalDraft,
    r: &mut FederalResult,
    id: i64,
    owner: usize,
    v: &crate::FederalBusiness,
    net_profit: i64,
    selected: Option<&crate::Section179PreparedAllocation>,
    home: Option<&crate::home_office::HomeContext>,
) -> Result<(), crate::Section179PreparedIssue> {
    let source = "https://www.irs.gov/instructions/i1040sc";
    let inputs = ["income.business"];
    let net_line = match v.activity {
        crate::BusinessActivity::Farming { .. } => return Ok(()),
        crate::BusinessActivity::Gambling { .. } => FormLine::new(TaxForm::ScheduleC, "31"),
        crate::BusinessActivity::Ordinary { receipts, returns, .. } => {
            let office = crate::section179_return::office(d, id, v, selected, home)?;
            let goods = v.inventory.cost();
            let cooperative = farm_cooperative(d, owner, id)?.taxable;
            let gross = v.receipts() + cooperative - goods;
            let depreciation =
                business_depreciation_with_section179(d, id, &v.assets, selected, home)?;
            emit_lines(
                r,
                &mut (),
                [
                    ("1", "gross_receipts", receipts, msg!("EXPLAIN_BUSINESS_N_N_N")),
                    (
                        "6",
                        "other_income",
                        v.receipts() + cooperative - receipts + returns,
                        msg!("EXPLAIN_BUSINESS_N_N_N_2"),
                    ),
                    (
                        "2",
                        "returns",
                        returns,
                        crate::Message::new("EXPLAIN_BUSINESS_RETURNS", alloc::vec![]),
                    ),
                    (
                        "3",
                        "net_receipts",
                        receipts - returns,
                        crate::Message::new("EXPLAIN_BUSINESS_NET_RECEIPTS", alloc::vec![]),
                    ),
                    (
                        "5",
                        "gross_profit",
                        receipts - returns - goods,
                        crate::Message::new("EXPLAIN_BUSINESS_GROSS_PROFIT", alloc::vec![]),
                    ),
                    ("7", "gross_income", gross, msg!("EXPLAIN_BUSINESS_N_N_N_3")),
                    ("13", "depreciation", depreciation, msg!("EXPLAIN_BUSINESS_N_N_N_4")),
                    (
                        "28",
                        "total_expenses",
                        gross - net_profit
                            + selected
                                .map_or(0, |allocation| allocation.ordinary_risk_adjustment(id))
                            - office,
                        msg!("EXPLAIN_BUSINESS_N_N_N_5"),
                    ),
                    (
                        "29",
                        "tentative_profit",
                        net_profit
                            - selected
                                .map_or(0, |allocation| allocation.ordinary_risk_adjustment(id))
                            + office,
                        msg!("EXPLAIN_BUSINESS_N_N_N_6"),
                    ),
                ],
                |(line, suffix, amount, explanation), _, _| {
                    Some(calculation_row(
                        Some(FormLine::new(TaxForm::ScheduleC, line)),
                        &alloc::format!("business_{id}_{suffix}"),
                        LineValue::MoneyCents(amount),
                        &inputs,
                        source,
                        explanation,
                    ))
                },
            );
            if let crate::BusinessInventory::Cost {
                opening,
                purchases,
                personal,
                labor,
                materials,
                other,
                closing,
                ..
            } = v.inventory
            {
                let total = opening + purchases - personal + labor + materials + other;
                emit_lines(
                    r,
                    &mut (),
                    [
                        (35, opening),
                        (36, purchases - personal),
                        (37, labor),
                        (38, materials),
                        (39, other),
                        (40, total),
                        (41, closing),
                        (42, goods),
                    ],
                    |(number, amount), _, _| {
                        Some(calculation_row(
                            Some(FormLine::new(TaxForm::ScheduleC, &alloc::format!("{number}"))),
                            &alloc::format!("business_{id}_inventory_line{number}"),
                            LineValue::MoneyCents(amount),
                            &inputs,
                            source,
                            crate::Message::new("EXPLAIN_BUSINESS_INVENTORY", alloc::vec![]),
                        ))
                    },
                );
            }
            for (index, item) in v.other_income.iter().enumerate() {
                line_cents(
                    r,
                    &alloc::format!("business_{id}_other_income_{index}"),
                    item.amount,
                    &["income.business.other_income"],
                    source,
                    crate::Message::new(
                        "EXPLAIN_BUSINESS_OTHER_INCOME",
                        alloc::vec![crate::MessageArg::Text(item.description.clone())],
                    ),
                );
            }
            FormLine::new(TaxForm::ScheduleC, "31")
        }
    };
    push_line(
        r,
        Some(net_line),
        &alloc::format!("business_{id}_net_profit"),
        net_profit,
        &inputs,
        source,
        msg!("EXPLAIN_BUSINESS_N_NET_PROFIT"),
    );
    Ok(())
}
// One asset's current bonus, MACRS, AMT depreciation and remaining-basis rows,
// each tagged with its Form 4562 line when the business or farm rental files
// that form (depreciation::form_4562_line). Shared by Schedule C and F
// businesses and by Form 4835 farm rentals.
fn form_4562_asset_lines(
    d: &FederalDraft,
    r: &mut FederalResult,
    id: i64,
    index: usize,
    asset: &crate::BusinessAsset,
    form_4562: bool,
) {
    let whole_asset = d.income.iter().find_map(|entry| match &entry.income {
        FederalIncome::FarmRental { data } if entry.id == id => data.assets.get(index),
        _ => None,
    });
    let asset = whole_asset.unwrap_or(asset);
    let mid_quarter = crate::depreciation::mid_quarter(d);
    let (regular, alternative) = match (
        crate::cooperative_basis::source_amounts(d, id, asset, mid_quarter, false),
        crate::cooperative_basis::source_amounts(d, id, asset, mid_quarter, true),
    ) {
        (Ok(regular), Ok(alternative)) => (regular, alternative),
        (Err(issue), _) | (_, Err(issue)) => {
            crate::section179_return::Issue::Prepared(issue).report(r);
            return;
        }
    };
    let regular_deduction = regular.bonus + regular.macrs;
    let alternative_deduction = alternative.bonus + alternative.macrs;
    for (suffix, amount, authority, explanation) in [
        (
            "bonus",
            regular.bonus,
            "https://www.irs.gov/irb/2026-13_IRB",
            msg!("EXPLAIN_BUSINESS_N_ASSET_N_N_BONUS"),
        ),
        (
            "macrs",
            regular.macrs,
            "https://www.irs.gov/publications/p946",
            msg!("EXPLAIN_BUSINESS_N_ASSET_N_N_MACRS"),
        ),
        (
            "amt_depreciation",
            alternative_deduction,
            "https://www.irs.gov/instructions/i6251",
            msg!("EXPLAIN_BUSINESS_N_ASSET_N_N_AMT_DEPRECIATION"),
        ),
        (
            "amt_remaining_basis",
            alternative.opening - alternative_deduction,
            "https://www.irs.gov/instructions/i6251",
            msg!("EXPLAIN_BUSINESS_N_ASSET_N_N_AMT_REMAINING_BASIS"),
        ),
        (
            "remaining_basis",
            // The recaptured excess depreciation is added back to the basis.
            regular.opening - regular_deduction
                + asset
                    .recapture()
                    .or_else(|| asset.section179_recapture())
                    .map_or(0, |recapture| recapture.excess()),
            "https://www.irs.gov/publications/p946",
            msg!("EXPLAIN_BUSINESS_N_ASSET_N_N_REMAINING_BASIS"),
        ),
    ] {
        let form_line_tag = form_4562
            .then(|| crate::depreciation::form_4562_line(asset, suffix))
            .flatten()
            .map(|line| FormLine::new(TaxForm::Form4562, line));
        push_line(
            r,
            form_line_tag,
            &alloc::format!("business_{}_asset_{}_{}", id, index, suffix),
            if whole_asset.is_some() {
                crate::community::income_amount(d, id, amount)
            } else {
                amount
            },
            &["income.business.assets"],
            authority,
            explanation,
        );
    }
}
// One business's Form 4562 line 12 (its allowed section 179 deduction) and
// line 22 (the total that Schedule C line 13 or Schedule F line 14 deducts:
// bonus, MACRS and the allowed section 179).
fn form_4562_totals_with_section179(
    d: &FederalDraft,
    r: &mut FederalResult,
    id: i64,
    assets: &[crate::BusinessAsset],
    selected: Option<&crate::Section179PreparedAllocation>,
    home: Option<&crate::home_office::HomeContext>,
) -> Result<(), crate::Section179PreparedIssue> {
    let section179 = crate::section179_return::allowed(d, id, selected, home)?;
    let total = business_depreciation_with_section179(d, id, assets, selected, home)?;
    emit_lines(
        r,
        &mut (),
        [
            ("12", "section179_deduction", section179, msg!("EXPLAIN_BUSINESS_N_N_N_7")),
            ("22", "depreciation_total", total, msg!("EXPLAIN_BUSINESS_N_N_N_8")),
        ],
        |(line, suffix, amount, explanation), _, _| {
            Some(calculation_row(
                Some(FormLine::new(TaxForm::Form4562, line)),
                &alloc::format!("business_{id}_{suffix}"),
                LineValue::MoneyCents(amount),
                &["income.business.assets"],
                "https://www.irs.gov/instructions/i4562",
                explanation,
            ))
        },
    );
    Ok(())
}
// Current bonus, MACRS and allowed section 179 of one business: Form 4562
// line 22, Schedule C line 13, Schedule F line 14.
pub(crate) fn business_depreciation_with_section179(
    d: &FederalDraft,
    id: i64,
    assets: &[crate::BusinessAsset],
    selected: Option<&crate::Section179PreparedAllocation>,
    home: Option<&crate::home_office::HomeContext>,
) -> Result<i64, crate::Section179PreparedIssue> {
    let mq = crate::depreciation::mid_quarter(d);
    let depreciation = if let Some(whole) = d.income.iter().find_map(|entry| match &entry.income {
        FederalIncome::FarmRental { data } if entry.id == id => Some(data),
        _ => None,
    }) {
        let amount = crate::cooperative_basis::depreciation(d, id, &whole.assets, mq, false)?;
        match crate::community::farm_rental_amount(d, id, |_| amount) {
            Some(amount) => amount,
            None => crate::cooperative_basis::depreciation(d, id, assets, mq, false)?,
        }
    } else {
        crate::cooperative_basis::depreciation(d, id, assets, mq, false)?
    };
    Ok(depreciation + crate::section179_return::allowed(d, id, selected, home)?)
}
// Form 4562 Part V Section A columns for one actual-expense vehicle: line 25
// (special allowance), then line 26 (more than 50% qualified business use) or
// line 27 (50% or less, ADS straight line).
fn vehicle_columns(
    r: &mut FederalResult,
    id: i64,
    index: usize,
    assets: &[crate::BusinessAsset],
    mileage: usize,
    mid_quarter: bool,
) {
    let asset = &assets[index];
    let row = if asset.predominant() { "26" } else { "27" };
    let inputs = ["income.business.assets"];
    let source = "https://www.irs.gov/instructions/i4562";
    let bonus = asset.bonus_amount();
    emit_lines(
        r,
        &mut (),
        [
            (
                "type",
                "a",
                if asset.automobile_limit().is_some() { 100 } else { 0 },
                Message::new(
                    "EXPLAIN_BUSINESS_N_ASSET_N_LISTED_N_TYPE",
                    alloc::vec![crate::BusinessAsset::display_arg(assets, index, mileage)],
                ),
            ),
            (
                "business_use",
                "c",
                asset.business_use_hundredths(),
                msg!("EXPLAIN_BUSINESS_N_ASSET_N_LISTED_N_BUSINESS_USE"),
            ),
            (
                "cost",
                "d",
                asset.cost - asset.credit_reduction,
                msg!("EXPLAIN_BUSINESS_N_ASSET_N_LISTED_N_COST"),
            ),
            (
                "depreciation_basis",
                "e",
                asset.opening_basis() - bonus,
                msg!("EXPLAIN_BUSINESS_N_ASSET_N_LISTED_N_DEPRECIATION_BASIS"),
            ),
            (
                "depreciation",
                "h",
                asset.macrs_amount(mid_quarter),
                msg!("EXPLAIN_BUSINESS_N_ASSET_N_LISTED_N_DEPRECIATION"),
            ),
            (
                "section179",
                "i",
                asset.elected179(),
                msg!("EXPLAIN_BUSINESS_N_ASSET_N_LISTED_N_SECTION179"),
            ),
        ],
        |(suffix, column, amount, explanation), _, _| {
            Some(calculation_row(
                Some(FormLine::new(TaxForm::Form4562, &alloc::format!("{row}({column})"))),
                &alloc::format!("business_{id}_asset_{index}_listed_{suffix}"),
                LineValue::MoneyCents(amount),
                &inputs,
                source,
                explanation,
            ))
        },
    );
    // Form 4797 Part IV: the vehicle's business use fell to 50% or less, so the
    // depreciation above what straight-line ADS would have allowed is income
    // (Schedule C line 6, which carries the excess in its other income).
    if let Some(recapture) = asset.recapture() {
        emit_lines(
            r,
            &mut (),
            [
                (
                    "35(b)",
                    "prior_depreciation",
                    recapture.allowed,
                    msg!("EXPLAIN_BUSINESS_N_ASSET_N_LISTED_PRIOR_DEPRECIATION"),
                ),
                (
                    "36(b)",
                    "recomputed",
                    recapture.recomputed,
                    msg!("EXPLAIN_BUSINESS_N_ASSET_N_LISTED_RECOMPUTED"),
                ),
                (
                    "37(b)",
                    "recapture",
                    recapture.excess(),
                    msg!("EXPLAIN_BUSINESS_N_ASSET_N_LISTED_RECAPTURE"),
                ),
            ],
            |(line, suffix, amount, explanation), _, _| {
                Some(calculation_row(
                    Some(FormLine::new(TaxForm::Form4797, line)),
                    &alloc::format!("business_{id}_asset_{index}_listed_{suffix}"),
                    LineValue::MoneyCents(amount),
                    &inputs,
                    "https://www.irs.gov/instructions/i4797",
                    explanation,
                ))
            },
        );
    }
    if bonus > 0 {
        push_line(
            r,
            Some(FormLine::new(TaxForm::Form4562, "25")),
            &alloc::format!("business_{id}_asset_{index}_listed_special_allowance"),
            bonus,
            &inputs,
            source,
            msg!("EXPLAIN_BUSINESS_N_ASSET_N_LISTED_SPECIAL_ALLOWANCE"),
        );
    }
}
// The earlier-year installment gains a section 1231 lookback makes ordinary,
// as qualified business income by the business the person named.
#[inline(never)]
fn installment_qbi_shares(
    d: &FederalDraft,
    rental: &crate::extended_rules::RentalResult,
    character: Option<&crate::section1231::Result1231>,
) -> Result<crate::installment::QbiShares, crate::section1231::SourceError> {
    crate::installment::qbi_shares(d, rental, character)
}
// A business no longer on the return is a stand-alone QBI activity with no W-2
// wages and no qualified property.
#[inline(never)]
fn standalone_installment_qbi(
    d: &FederalDraft,
    shares: &crate::installment::QbiShares,
    activities: &mut Vec<crate::business_rules::QbiActivity>,
) {
    for (_, part, owner) in shares.iter().filter(|(business, _, _)| {
        business.is_none_or(|id| {
            !d.income
                .iter()
                .any(|e| e.id == id && matches!(e.income, FederalIncome::Business { .. }))
        })
    }) {
        activities.push(crate::business_rules::QbiActivity {
            source_wages_cents: None,
            source_property_cents: None,
            source_income_cents: None,
            owner: Some(*owner),
            income: *part,
            wages: 0,
            property: 0,
            active: true,
            service: Some(false),
            group: None,
        });
    }
}
// One business asset's Form 4797 rows and the Form 8949 row of the personal-use
// part of its sale.
#[inline(never)]
#[allow(clippy::too_many_arguments)]
fn asset_disposition_rows(
    d: &FederalDraft,
    t: &mut Totals,
    r: &mut FederalResult,
    #[cfg(test)] source: &str,
    mid_quarter: bool,
    id: i64,
    index: usize,
    assets: &[crate::BusinessAsset],
    mileage: usize,
) {
    let sale = match crate::cooperative_basis::sale(d, id, &assets[index], mid_quarter, false) {
        Ok(sale) => sale,
        Err(issue) => {
            crate::section179_return::Issue::Prepared(issue).report(r);
            return;
        }
    };
    let partial = match crate::cooperative_basis::partial(d, id, &assets[index], mid_quarter, false)
    {
        Ok(partial) => partial,
        Err(issue) => {
            crate::section179_return::Issue::Prepared(issue).report(r);
            return;
        }
    };
    crate::asset_sale::report_business_asset(
        r,
        #[cfg(test)]
        source,
        &crate::IssueContext::income_id(id),
        &alloc::format!("business_{id}_asset_{index}"),
        index,
        assets,
        mileage,
        sale,
        partial,
        "income.business.assets",
    );
    t.personal_part(r, id, crate::BusinessAsset::display_arg(assets, index, mileage), sale);
}
// The personal-use part of an employee vehicle's sale is a Form 8949 row under
// a record number no income entry has.
#[inline(never)]
fn employee_personal_parts(
    d: &FederalDraft,
    t: &mut Totals,
    r: &mut FederalResult,
    employee: &crate::employee_expenses::Calculation,
) {
    for (position, form) in employee.forms.iter().enumerate() {
        let assets = form.claim.assets();
        for index in 0..assets.len() {
            t.personal_part(
                r,
                crate::asset_sale::employee_source_id(position),
                crate::BusinessAsset::display_arg(&assets, index, form.claim.mileage.len()),
                assets[index].sale_for(crate::depreciation::mid_quarter(d), false),
            );
        }
    }
}
// The personal-use part of a sold rental: a gain is a capital gain on Form
// 8949 (box F, or C within a year of the first building), a loss is not
// deductible (Pub 544, "Property Used Partly for Business or Rental").
#[inline(never)]
fn rental_personal_part(
    t: &mut Totals,
    r: &mut FederalResult,
    entry: &FederalIncomeEntry,
    data: &crate::FederalRental,
) {
    if crate::asset_sale::rental_sale_refusal(data).is_none()
        && let Ok(Some(sale)) = crate::asset_sale::rental_sale(data, false)
        && sale.personal > 0
        && let Some(date) = data.sale.date()
    {
        let first = data.buildings.iter().map(|b| b.in_service).min().unwrap_or(date);
        t.property_row(
            r,
            entry.id,
            crate::interview::income_display_arg(entry),
            crate::dates::held_more_than_one_year(first, date),
            [sale.personal_proceeds, sale.personal_basis, 0],
            true,
        );
    }
}
// The sale of a business as a whole (Form 8594), beside each asset's own row:
// the inventory is Schedule C line 1 (already in the business's receipts), the
// self-created goodwill and going-concern value one long-term Form 8949 row (a
// capital asset with no basis, not section 1231 and not qualified business
// income, and outside net investment income of a business you materially
// participate in), and the covenant not to compete Schedule 1 line 8z.
#[inline(never)]
fn business_sale_rows(
    t: &mut Totals,
    r: &mut FederalResult,
    entry: &FederalIncomeEntry,
    sale: &crate::BusinessSale,
) {
    let source = "https://www.irs.gov/instructions/i8594";
    // Rows without a form line of their own: the amounts are already in the
    // business's receipts and in Schedule 1 line 8z's total.
    for (suffix, amount, explanation) in [
        ("sale_inventory", sale.inventory, msg!("EXPLAIN_BUSINESS_N_SALE_INVENTORY")),
        ("sale_covenant", sale.covenant, msg!("EXPLAIN_BUSINESS_N_SALE_COVENANT")),
    ] {
        if amount != 0 {
            push_line(
                r,
                None,
                &alloc::format!("business_{}_{suffix}", entry.id),
                amount,
                &["income.business.more.sale"],
                source,
                explanation,
            );
        }
    }
    t.other_8z += sale.covenant;
    if sale.goodwill != 0 {
        let gain = sale.goodwill;
        t.property_row(
            r,
            entry.id,
            crate::interview::income_display_arg(entry),
            true,
            [dollars(gain), 0, 0],
            false,
        );
        // Form 8960 line 5b: gain on property held in a business you
        // materially participate in.
        t.k1_nii_excluded -= dollars(gain) * 100;
    }
}
// The sale, scrapping or condemnation of equipment rented out outside a
// business: depreciable property, but not property used in a trade or business
// (section 1231(b)(1)). Section 1245 still takes the depreciation allowed as
// ordinary income, Part III line 32 to line 13 (Schedule 1 line 4, not
// self-employment income); a gain above it, or a loss, is a capital gain or
// loss on Form 8949 (i4797 "Sale of Home Used for Business": an activity that
// does not rise to a trade or business is a capital gain or loss). Both are
// investment income. A loss on a sale to a related buyer is not deductible
// (section 267) and the whole gain of a controlled buyer's purchase is ordinary
// (section 1239).
#[inline(never)]
fn personal_equipment_sale(
    t: &mut Totals,
    r: &mut FederalResult,
    entry: &FederalIncomeEntry,
    index: usize,
    assets: &[crate::BusinessAsset],
    mid_quarter: bool,
) {
    let Some(sale) = assets[index].sale_for(mid_quarter, false) else {
        return;
    };
    let sale = &sale;
    let label = crate::BusinessAsset::display_arg(assets, index, 0);
    if sale.disallowed > 0 {
        note_once_scoped(
            r,
            Message::new("NOTE_SALE_TO_RELATIVE_LOSS_DISALLOWED", alloc::vec![label]),
            crate::interview::income_issue_context(entry),
        );
        return;
    }
    let ordinary = crate::asset_sale::equipment_ordinary(sale);
    let prefix = alloc::format!("personal_rental_{}_asset_{}_disposal", entry.id, index);
    if sale.gain > 0 {
        emit_lines(
            r,
            &mut (),
            [
                ("22", "sale_price", sale.realized, msg!("EXPLAIN_ASSET_SALE_N_6")),
                ("23", "cost", sale.basis, msg!("EXPLAIN_ASSET_SALE_N_7")),
                ("24", "depreciation", sale.depreciation, msg!("EXPLAIN_ASSET_SALE_N_8")),
                (
                    "25",
                    "adjusted_basis",
                    sale.basis - sale.depreciation,
                    msg!("EXPLAIN_ASSET_SALE_N_4"),
                ),
                ("26", "gain", sale.gain, msg!("EXPLAIN_ASSET_SALE_N_5")),
                ("27b", "1245_recapture", ordinary, msg!("EXPLAIN_N_N_RECAPTURE_2")),
            ],
            |(line, suffix, amount, explanation), _, _| {
                Some(calculation_row(
                    Some(FormLine::new(TaxForm::Form4797, line)),
                    &alloc::format!("{prefix}_{suffix}"),
                    LineValue::MoneyCents(amount * 100),
                    &["income.nonbusiness_property.assets"],
                    "https://www.irs.gov/instructions/i4797",
                    explanation,
                ))
            },
        );
    }
    // The ordinary recapture joins Schedule 1 line 4 through the property
    // sources; the capital part is one Form 8949 row.
    t.property_row(
        r,
        entry.id,
        label,
        sale.long,
        [sale.realized, sale.basis - sale.depreciation, -ordinary],
        true,
    );
}
pub(crate) fn valid_birth(date: u32) -> bool {
    date / 10000 <= 2026 && valid_date(date)
}
// A date a rental can first be available to rent on a 2026 return: through
// 2027, the year an exchange's replacement property can still be received
// (section 1031(a)(3)); not a birth date.
pub(crate) fn valid_service_date(date: u32) -> bool {
    date / 10000 <= 2027 && valid_date(date)
}
pub(crate) fn valid_date(date: u32) -> bool {
    let y = date / 10000;
    let m = date / 100 % 100;
    let d = date % 100;
    let days = crate::dates::days_in_month(y, m);
    (1850..=9999).contains(&y) && (1..=days).contains(&d)
}
// One Form 1099-SA's amounts onto the totals and the return lines: Form 8853 Section A for
// an Archer MSA, Section B for a Medicare Advantage MSA, and the death-of-the-holder income
// of an inherited account (Form 8889 lines 14a-16 for an HSA).
fn medical_distribution(
    r: &mut FederalResult,
    t: &mut Totals,
    e: &FederalIncomeEntry,
    context: &crate::IssueContext,
    data: &crate::FederalMedicalDistribution,
    amounts: &crate::medical_account::SaAmounts,
    owner: usize,
) -> Result<(), crate::medical_account::OutputFailure> {
    use crate::{MedicalSaAccount as A, MedicalSaPayment as P};
    let id = e.id;
    let native = |amount: &Exact| crate::medical_account::required_output(amount, context.clone());
    if matches!(data.account, A::Hsa) && !matches!(data.payment, P::Inherited { .. }) {
        let totals = &mut t.hsa_distributions[owner];
        totals.gross += exact::whole(data.gross);
        totals.taxable += &amounts.taxable;
        totals.penalized += &amounts.penalized;
        match &data.payment {
            P::Own { medical, rollover, .. } => {
                totals.medical += exact::whole(*medical);
                totals.rollover +=
                    rollover.as_ref().map_or_else(|| exact::whole(0), |v| v.amount());
            }
            P::Unreported { event: crate::MedicalDeemed::Pledged { .. }, .. } => {
                totals.deemed += &amounts.taxable;
                totals.pledged += &amounts.taxable;
                totals.pledged_penalized += &amounts.penalized;
            }
            P::Prohibited { .. } | P::Unreported { .. } => totals.deemed += &amounts.taxable,
            P::ExcessReturned { .. } => totals.returned_excess += exact::whole(data.gross),
            _ => {}
        }
        return Ok(());
    }
    match &data.payment {
        P::Own { medical, rollover, .. } => {
            let rolled = rollover.as_ref().map_or_else(|| exact::whole(0), |v| v.amount());
            if let Some(form) = data.medicare_form(id, owner, context.clone(), amounts) {
                line_cents(
                    r,
                    &alloc::format!("medicare_msa_{id}_taxable"),
                    native(&amounts.taxable)?,
                    &["income.medical_distribution"],
                    "https://www.irs.gov/instructions/i8853",
                    msg!("EXPLAIN_MEDICARE_MSA_N_N"),
                );
                t.medicare_forms.push(form);
            } else {
                t.archer_msa += &amounts.taxable;
                t.archer_msa_owner[owner] += &amounts.taxable;
                t.archer_penalized += &amounts.penalized;
                emit_lines(
                    r,
                    &mut (),
                    [
                        ("gross", data.gross),
                        ("medical", *medical),
                        ("rollover", native(&rolled)?),
                        ("taxable", native(&amounts.taxable)?),
                        ("penalty_base", native(&amounts.penalized)?),
                    ],
                    |(suffix, amount), _, _| {
                        Some(calculation_row(
                            None,
                            &alloc::format!("archer_msa_{id}_{suffix}"),
                            LineValue::MoneyCents(amount),
                            &["income.medical_distribution"],
                            "https://www.irs.gov/instructions/i8853",
                            msg!("EXPLAIN_ARCHER_MSA_N_N"),
                        ))
                    },
                );
            }
        }
        P::Prohibited { .. } | P::Unreported { .. } => {
            if let Some(form) = data.medicare_form(id, owner, context.clone(), amounts) {
                emit_lines(
                    r,
                    &mut (),
                    [("taxable", native(&amounts.taxable)?), ("deemed", data.gross)],
                    |(suffix, amount), _, _| {
                        Some(calculation_row(
                            None,
                            &alloc::format!("medicare_msa_{id}_{suffix}"),
                            LineValue::MoneyCents(amount),
                            &["income.medical_distribution"],
                            "https://www.irs.gov/instructions/i8853",
                            msg!("EXPLAIN_MEDICARE_MSA_N_N"),
                        ))
                    },
                );
                t.medicare_forms.push(form);
            } else {
                t.archer_msa += &amounts.taxable;
                t.archer_msa_owner[owner] += &amounts.taxable;
                t.archer_penalized += &amounts.penalized;
                emit_lines(
                    r,
                    &mut (),
                    [
                        ("gross", data.gross),
                        ("deemed", data.gross),
                        ("taxable", native(&amounts.taxable)?),
                        ("penalty_base", native(&amounts.penalized)?),
                    ],
                    |(suffix, amount), _, _| {
                        Some(calculation_row(
                            None,
                            &alloc::format!("archer_msa_{id}_{suffix}"),
                            LineValue::MoneyCents(amount),
                            &["income.medical_distribution"],
                            "https://www.irs.gov/instructions/i8853",
                            msg!("EXPLAIN_ARCHER_MSA_N_N"),
                        ))
                    },
                );
            }
        }
        P::ExcessReturned { .. } => {
            t.archer_excess_earnings += &amounts.earnings;
            line_cents(
                r,
                &alloc::format!("archer_msa_{id}_excess_earnings"),
                native(&amounts.earnings)?,
                &["income.medical_distribution"],
                "https://www.irs.gov/pub/irs-pdf/f1099sa.pdf",
                msg!("EXPLAIN_ARCHER_MSA_N_EXCESS_EARNINGS"),
            );
        }
        P::Inherited { died, value, beneficiary } => {
            let slot = match data.account {
                A::Hsa => 0,
                A::MedicareAdvantage { .. } => 2,
                A::Archer | A::MedicareFromSpouse => 1,
            };
            t.inherited_medical[slot] += &amounts.inherited;
            t.inherited_medical_earnings += &amounts.earnings;
            let source = if slot == 0 {
                "https://www.irs.gov/instructions/i8889"
            } else {
                "https://www.irs.gov/instructions/i8853"
            };
            for (suffix, amount, whole) in [
                ("value", exact::whole(dollars(*value)), true),
                ("medical", amounts.inherited_medical.clone(), true),
                ("taxable", amounts.inherited.clone(), true),
                ("earnings", amounts.earnings.clone(), false),
            ] {
                let id_text = alloc::format!("inherited_medical_{id}_{suffix}");
                if whole {
                    let cents = &amount * exact::whole(100);
                    if suffix == "taxable" {
                        native(&cents)?;
                    } else if crate::medical_account::explanation_output(&cents, context.clone(), r)
                        .is_none()
                    {
                        continue;
                    }
                    line(
                        r,
                        &id_text,
                        native(&amount)?,
                        &["income.medical_distribution"],
                        source,
                        msg!("EXPLAIN_INHERITED_MEDICAL_N_N"),
                    );
                } else {
                    line_cents(
                        r,
                        &id_text,
                        native(&amount)?,
                        &["income.medical_distribution"],
                        source,
                        msg!("EXPLAIN_INHERITED_MEDICAL_N_N"),
                    );
                }
            }
            if died / 10000 < 2026 {
                r.review_notes.push(ReviewNote::localized(
                    #[cfg(test)] alloc::format!("Inherited medical account — {}: death-date value and qualifying medical offsets belong to the {} return, including any required amendment. They are not included or deducted again in 2026. Earnings after the death are calculated in this entry.", e.label, died / 10000),
                    Message::new("NOTE_INHERITED_MEDICAL_PRIOR_YEAR", alloc::vec![
                        crate::interview::income_display_arg(e), MessageArg::Number((died / 10000) as i64),
                    ]),
                ));
            } else {
                r.review_notes.push(ReviewNote::localized(
                    #[cfg(test)] alloc::format!("Inherited medical account — {}: retain an account-specific death statement and medical payment records. Payments within one year may change this death-year calculation; earnings after the death are the part of box 1 above box 4.", e.label),
                    Message::new("NOTE_INHERITED_MEDICAL_DEATH_RECORDS", alloc::vec![crate::interview::income_display_arg(e)]),
                ));
            }
            if amounts.decline {
                r.review_notes.push(ReviewNote::localized(
                    #[cfg(test)] alloc::format!("Inherited medical account — {}: the account paid out less than its value at the death. No deduction is available for the decline; only earnings above that value would be income.", e.label),
                    Message::new("NOTE_INHERITED_MEDICAL_DECLINE", alloc::vec![crate::interview::income_display_arg(e)]),
                ));
            }
            let _ = beneficiary;
        }
    }
    Ok(())
}

pub(crate) fn joint(s: FederalStatus) -> bool {
    s == FederalStatus::Joint
}

pub(crate) fn brackets(s: FederalStatus) -> [i64; 6] {
    crate::income_tax::Rates::for_year(2026, s).unwrap().ordinary
}

pub(crate) fn salt_cap_current_year(status: FederalStatus, magi: i64) -> i64 {
    // Section 164(b)(7) phases down the full cap, floors it at $10,000, and
    // only then halves the result for a married-separate return.
    let threshold = if status == FederalStatus::Separate {
        crate::year_constants::SALT_PHASEDOWN_THRESHOLD_SEPARATE_DOLLARS
    } else {
        crate::year_constants::SALT_PHASEDOWN_THRESHOLD_DOLLARS
    };
    let full = phase::floor(
        crate::year_constants::SALT_REDUCED_CAP_FLOOR_DOLLARS,
        crate::year_constants::SALT_CAP_DOLLARS - fraction(positive(magi - threshold), 30, 100),
    );
    if status == FederalStatus::Separate { fraction(full, 1, 2) } else { full }
}
pub(crate) fn preferential_tax(income: i64, preferential: i64, status: FederalStatus) -> i64 {
    preferential_tax_with_collectibles(income, preferential, 0, status)
}
// Schedule D Tax Worksheet without a Form 4952 election.
// `preferential` includes all net long-term gain and qualified dividends;
// `collectibles` is the loss-adjusted 28% component, capped by net capital gain upstream.
pub(crate) fn preferential_tax_with_collectibles(
    income: i64,
    preferential: i64,
    collectibles: i64,
    status: FederalStatus,
) -> i64 {
    preferential_tax_with_special_gains(income, preferential, collectibles, 0, status)
}
pub(crate) fn preferential_tax_with_special_gains(
    income: i64,
    preferential: i64,
    collectibles: i64,
    unrecaptured: i64,
    status: FederalStatus,
) -> i64 {
    let preferential = positive(preferential);
    let unrecaptured = phase::cap(positive(unrecaptured), [preferential]);
    let collectibles = phase::cap(positive(collectibles), [preferential - unrecaptured]);
    schedule_d_tax(
        income,
        preferential,
        collectibles + unrecaptured,
        unrecaptured,
        collectibles > 0,
        status,
    )
}
// Schedule D lines 12 and 35 are distinct inputs for the Form 8615 family
// worksheet: allocated special gains versus original Schedule D line 19 totals.
pub(crate) fn schedule_d_tax(
    income: i64,
    preferential: i64,
    special: i64,
    original_unrecaptured: i64,
    has_collectibles: bool,
    status: FederalStatus,
) -> i64 {
    crate::income_tax::Rates::with_method(2026, status, true).unwrap().schedule_d(
        income,
        preferential,
        special,
        original_unrecaptured,
        has_collectibles,
    )
}
// Notice 2025-67 supplies 2026 boundaries; Form 8880 supplies the worksheet.
// Surviving-spouse status uses the "all other" Saver's Credit band, not joint brackets.
pub(crate) fn saver_rate(agi: i64, status: FederalStatus) -> i64 {
    let limits = match status {
        FederalStatus::Joint => crate::year_constants::SAVER_AGI_LIMITS_JOINT_DOLLARS,
        FederalStatus::Head => crate::year_constants::SAVER_AGI_LIMITS_HEAD_DOLLARS,
        _ => crate::year_constants::SAVER_AGI_LIMITS_OTHER_DOLLARS,
    };
    if agi <= limits[0] {
        50
    } else if agi <= limits[1] {
        20
    } else if agi <= limits[2] {
        10
    } else {
        0
    }
}

fn saver_potential_with_sources(
    facts: &FederalSaver,
    people: &FederalPeople,
    status: FederalStatus,
    agi: i64,
) -> Result<(i64, [i64; 2]), (&'static str, &'static str)> {
    let j = joint(status);
    if !j
        && (facts.spouse_able != 0
            || facts.spouse_contributions != 0
            || facts.distributions.iter().any(|d| d.owner == Owner::Spouse))
    {
        return Err((
            "ISSUE_SAVER_SPOUSE_REQUIRES_JOINT_RETURN",
            "Spouse contributions and distributions belong only on a joint return. Revisit Saver’s Credit after a filing-status change.",
        ));
    }
    let mut offsets = [0, 0];
    for d in &facts.distributions {
        let owner = if d.owner == Owner::Taxpayer { 0 } else { 1 };
        offsets[owner] += d.amount;
        // A recipient's own withdrawals always reduce their base. Cross-spouse reductions
        // depend on filing together in the distribution year, even if the recipient is ineligible.
        // An undecided 2027 status is assumed joint (the smaller credit).
        if j && (d.year() == SaverDistributionYear::TaxYear
            || d.joint_with_current_spouse() != Answer::No)
        {
            offsets[1 - owner] += d.amount;
        }
    }
    let contributions = [
        facts.taxpayer_contributions + facts.taxpayer_able,
        facts.spouse_contributions + facts.spouse_able,
    ];
    let persons = [Some(&people.taxpayer), if j { people.spouse.as_ref() } else { None }];
    let eligible: [i64; 2] = core::array::from_fn(|i| {
        // Form 8880 prints "born after January 1, 2009": the day-before rule.
        if persons[i].is_some_and(|p| {
            p.attained(18, true) && !p.full_time_student && !p.dependency.claimable()
        }) {
            // Aggregate source cents within each worksheet line before whole-dollar rounding.
            phase::cap(positive(dollars(contributions[i]) - dollars(offsets[i])), [2000])
        } else {
            0
        }
    });
    Ok((fraction(eligible.iter().sum(), saver_rate(agi, status), 100), eligible))
}
#[cfg(test)]
pub(crate) fn saver_potential(
    facts: &FederalSaver,
    people: &FederalPeople,
    status: FederalStatus,
    agi: i64,
) -> Result<i64, (&'static str, &'static str)> {
    saver_potential_with_sources(facts, people, status, agi).map(|(amount, _)| amount)
}

// Schedule 1-A deliberately floors tips/overtime phaseout steps but CEILS vehicle steps.
pub(crate) fn additional_deductions(
    agi: i64,
    status: FederalStatus,
    tips: i64,
    overtime: i64,
    vehicle: i64,
) -> [i64; 3] {
    let j = joint(status);
    let work_reduction = phase::steps(
        agi - if j {
            crate::year_constants::SCHEDULE_1A_WORK_PHASEOUT_START_JOINT_DOLLARS
        } else {
            crate::year_constants::SCHEDULE_1A_WORK_PHASEOUT_START_SINGLE_DOLLARS
        },
        1000,
        phase::StepRounding::Down,
    ) * crate::year_constants::SCHEDULE_1A_WORK_REDUCTION_PER_THOUSAND_DOLLARS;
    [
        if status == FederalStatus::Separate {
            0
        } else {
            positive(
                phase::cap(tips, [crate::year_constants::SCHEDULE_1A_TIPS_CAP_DOLLARS])
                    - work_reduction,
            )
        },
        if status == FederalStatus::Separate {
            0
        } else {
            positive(
                phase::cap(
                    overtime,
                    [if j {
                        crate::year_constants::SCHEDULE_1A_OVERTIME_CAP_JOINT_DOLLARS
                    } else {
                        crate::year_constants::SCHEDULE_1A_OVERTIME_CAP_SINGLE_DOLLARS
                    }],
                ) - work_reduction,
            )
        },
        positive(
            phase::cap(vehicle, [crate::year_constants::SCHEDULE_1A_VEHICLE_INTEREST_CAP_DOLLARS])
                - phase::steps(
                    agi - if j {
                        crate::year_constants::SCHEDULE_1A_VEHICLE_PHASEOUT_START_JOINT_DOLLARS
                    } else {
                        crate::year_constants::SCHEDULE_1A_VEHICLE_PHASEOUT_START_SINGLE_DOLLARS
                    },
                    1000,
                    phase::StepRounding::Up,
                ) * crate::year_constants::SCHEDULE_1A_VEHICLE_REDUCTION_PER_THOUSAND_DOLLARS,
        ),
    ]
}

pub(crate) fn social_taxable(
    benefits: i64,
    other: i64,
    exempt: i64,
    status: FederalStatus,
    apart: bool,
) -> i64 {
    // Pub. 915 Worksheet 1 excludes the student-loan deduction from adjustments here.
    let provisional = positive((other + exempt) * 100 + benefits * 50);
    if status == FederalStatus::Separate && !apart {
        return dollars(phase::cap(benefits * 85, [fraction(provisional, 85, 100)]));
    }
    let (base, band) = if joint(status) {
        (
            crate::year_constants::SOCIAL_SECURITY_BASE_JOINT_DOLLARS,
            crate::year_constants::SOCIAL_SECURITY_BAND_JOINT_DOLLARS,
        )
    } else {
        (
            crate::year_constants::SOCIAL_SECURITY_BASE_OTHER_DOLLARS,
            crate::year_constants::SOCIAL_SECURITY_BAND_OTHER_DOLLARS,
        )
    };
    let excess = positive(provisional - base * 100);
    dollars(phase::cap(
        benefits * 85,
        [phase::cap(
            benefits * 50,
            [crate::kernel::ratio::trunc_i64(phase::cap(excess, [band * 100]), 2)],
        ) + fraction(positive(excess - band * 100), 85, 100)],
    ))
}

// A stored refusal list: each a refusal kind (other kinds live in their
// records), each once. Membership and uniqueness need no separate count cap.
fn only_refusals<T: PartialEq>(items: &[T], refused: impl Fn(&T) -> Option<Refusal>) -> bool {
    items.iter().enumerate().all(|(i, item)| refused(item).is_some() && !items[..i].contains(item))
}

impl FederalDraft {
    // Qualification remains a personal fact. For section 469 a joint return
    // is one taxpayer once either spouse separately qualifies (Reg. 1.469-9(c)(4)).
    // This calculation context never replaces either person's source record.
    pub(crate) fn professional(&self, owner: Owner) -> Option<crate::ProfessionalRentals> {
        let people = self.people.as_ref()?;
        if !self.professional_joint() {
            return people.professional(owner).cloned();
        }
        if !people.any_professional() {
            return None;
        }
        let elected = [Owner::Taxpayer, Owner::Spouse]
            .into_iter()
            .any(|o| people.professional(o).is_some_and(|p| p.single_activity));
        Some(crate::ProfessionalRentals {
            single_activity: elected,
            // The documented safe harbor covers the combined activity only
            // with the election; otherwise retain the owner's per-rental answer.
            over_500_hours: if elected {
                [Owner::Taxpayer, Owner::Spouse]
                    .into_iter()
                    .any(|o| people.professional(o).is_some_and(|p| p.over_500_hours))
            } else {
                people.professional(owner).is_some_and(|p| p.over_500_hours)
            },
        })
    }
    pub(crate) fn professional_joint(&self) -> bool {
        self.setup.as_ref().is_some_and(|s| s.filing_status() == FederalStatus::Joint)
    }
    pub(crate) fn professional_group_owner(&self, owner: Owner) -> Owner {
        let owner = crate::community::professional_owner(self.setup.as_ref(), owner);
        if self.professional_joint() && self.professional(owner).is_some_and(|p| p.single_activity)
        {
            Owner::Taxpayer
        } else {
            owner
        }
    }
    // Keep the existing elected person's editor authoritative. A newly
    // qualified spouse's default false is never an election revocation.
    pub(crate) fn professional_election_editor(&self, opening: Owner) -> Owner {
        if !self.professional_joint() {
            return opening;
        }
        let Some(people) = &self.people else {
            return opening;
        };
        [Owner::Taxpayer, Owner::Spouse]
            .into_iter()
            .find(|o| people.professional(*o).is_some_and(|p| p.single_activity))
            .or_else(|| {
                [Owner::Taxpayer, Owner::Spouse]
                    .into_iter()
                    .find(|o| people.professional(*o).is_some())
            })
            .unwrap_or(opening)
    }
    pub(crate) fn professional_elections(&self, opening: Owner) -> alloc::vec::Vec<i32> {
        if self.professional_election_editor(opening) == opening {
            alloc::vec![0, 1]
        } else {
            alloc::vec![i32::from(self.professional(opening).is_some_and(|p| p.single_activity))]
        }
    }
    pub(crate) fn reconcile_professional_election(&mut self, before: &Self, edited: Owner) {
        if !before.professional_joint() {
            return;
        }
        let prior = before.professional(edited).is_some_and(|p| p.single_activity);
        let authoritative = before.professional_election_editor(edited) == edited;
        let elected = if authoritative {
            self.people
                .as_ref()
                .and_then(|p| p.professional(edited))
                .map_or(prior, |p| p.single_activity)
        } else {
            prior
        };
        // Removing qualification transfers an existing joint election to the
        // remaining qualifier. It does not erase that spouse's qualification
        // or either person's own safe-harbor/history facts.
        let previous_editor = before.professional_election_editor(edited);
        let editor =
            if self.people.as_ref().is_some_and(|p| p.professional(previous_editor).is_some()) {
                previous_editor
            } else {
                self.professional_election_editor(edited)
            };
        let Some(people) = self.people.as_mut() else {
            return;
        };
        if let Some(p) = people.taxpayer.real_estate_professional.as_mut() {
            p.single_activity = elected && editor == Owner::Taxpayer;
        }
        if let Some(p) = people.spouse.as_mut().and_then(|p| p.real_estate_professional.as_mut()) {
            p.single_activity = elected && editor == Owner::Spouse;
        }
    }
    pub(crate) fn any_professional(&self) -> bool {
        self.people.as_ref().is_some_and(|p| p.any_professional())
    }
    pub(crate) fn empty(cookie: String) -> Self {
        Self {
            tax_year: 2026,
            next_id: 1,
            home_sites: Vec::new(),
            cookie,
            revision: 0,
            setup: None,
            people: None,
            dependents: Vec::new(),
            income: Vec::new(),
            finished_sections: Vec::new(),
            adjustments: None,
            deductions: None,
            credits: None,
            screening: None,
            // Estimated and extension payments are answered on the federal
            // payments page (M3-P13): a new return starts at zero.
            payments: Some(FederalPayments::none()),
            finished: false,
            situations: Vec::new(),
            adjustment_refusals: Vec::new(),
            credit_refusals: Vec::new(),
            tax_refusals: Vec::new(),
            coverdell_excess: Vec::new(),
            // The opening checklist starts with nothing ticked (M3-P18).
            checklist: crate::Checklist::NONE,
            injured_spouse: None,
        }
    }
    pub(crate) fn first_incomplete(&self) -> i32 {
        if self.setup.is_none() {
            0
        } else if self.people.is_none() {
            1
        } else if !self.finished_sections.contains(&crate::TaxSection::Income) {
            3
        } else if self.adjustments.is_none() {
            4
        } else if self.deductions.is_none() {
            5
        } else if self.credits.is_none() {
            6
        } else if self.screening.is_none() {
            7
        } else {
            9
        }
    }
    // The people you support.
    pub(crate) fn dependents(&self) -> &[FederalDependent] {
        &self.dependents
    }
    // Whether a separately filing spouse itemizes, which forces itemizing
    // (the deductions page's route).
    pub(crate) fn spouse_itemizes(&self) -> bool {
        self.setup.as_ref().is_some_and(|s| s.filing_status() == FederalStatus::Separate)
            && self.deductions.as_ref().is_some_and(|d| d.spouse_itemizes)
    }
    pub(crate) fn valid_stored(&self) -> bool {
        self.stored_issue().is_none()
    }
    pub(crate) fn stored_issue(&self) -> Option<crate::validation::ValidationIssue> {
        if let Some((_, issue)) = crate::cohorts::source_issue(self) {
            return Some(issue);
        }
        if let Some(issue) = crate::timber::return_issue(self) {
            return Some(issue);
        }
        if let Some(issue) = crate::home_sites::graph_issue(self) {
            return Some(issue);
        }
        let mut issue = None;
        if self.valid_stored_with_issue(&mut issue) {
            None
        } else {
            Some(issue.unwrap_or_else(|| {
                crate::validation::ValidationIssue::new(
                    "ISSUE_INTERVIEW_REVIEW_THE_ACCEPTED_PAGE_VALUES_BEFORE_65B6D7B7",
                )
            }))
        }
    }
    fn valid_stored_with_issue(
        &self,
        issue: &mut Option<crate::validation::ValidationIssue>,
    ) -> bool {
        if crate::retained_research::rule(self).is_some() {
            return false;
        }
        if crate::farm_specials::external_source_rule(self).is_some()
            || crate::medical_rollover::correction_reference_rule(self).is_some()
            || crate::hsa_funding::source_reference_rule(self).is_some()
            || crate::injured_spouse_sources::reference_rule(self).is_some()
            || crate::qbi_aggregation::accepted_rule(self).is_some()
        {
            return false;
        }
        if self.tax_year != 2026
            || self.cookie.is_empty()
            || self.revision < 0
            // Accepted revision must have a representable next i64 revision.
            || self.revision == i64::MAX
            || self.next_id < 1
            // The managed i64 allocator must have a representable successor.
            || self.next_id == i64::MAX
            || self.screening.as_ref().is_some_and(|screening| {
                crate::foreign_accounts::rule(
                    screening.foreign_account,
                    screening.fbar_required,
                    &screening.fbar_countries,
                )
                .is_some()
            })
            || crate::coverdell::accepted_rule(&self.coverdell_excess, self).is_some()
            || !only_refusals(
                &self.adjustment_refusals,
                crate::MoreAdjustment::refused,
            )
            // Notice kinds remain unique; their set has no independent count cap.
            || self.credit_refusals.iter().enumerate().any(|(index, kind)| {
                self.credit_refusals[..index].contains(kind)
            })
            || !only_refusals(&self.tax_refusals, crate::OtherTaxRefusal::refused)
        {
            return false;
        }
        let ids: Vec<i64> = self
            .income
            .iter()
            .map(|v| v.id)
            .chain(self.dependents().iter().map(|v| v.id))
            .chain(
                self.income
                    .iter()
                    .flat_map(|entry| crate::rental_energy::ids(&entry.income))
                    .filter(|id| *id != 0),
            )
            .chain(self.deductions.iter().flat_map(|d| d.appraisals.iter().map(|a| a.id)))
            .chain(
                self.income
                    .iter()
                    .flat_map(|v| crate::investment_statements::annual_ids(&v.income)),
            )
            .chain(self.income.iter().flat_map(|e| match &e.income {
                FederalIncome::EstateTrustPortfolio { data } => {
                    data.activities.activities.iter().map(|a| a.id).collect::<Vec<_>>()
                }
                _ => Vec::new(),
            }))
            .chain(
                self.credits
                    .as_ref()
                    .and_then(|c| crate::marketplace::facts(&c.marketplace))
                    .into_iter()
                    .flat_map(|f| {
                        f.forms
                            .iter()
                            .map(|r| r.id)
                            .chain(f.other_families.iter().map(|r| r.id))
                            .chain(f.covered.iter().map(|r| r.id))
                            .chain(f.qsehra.iter().map(|r| r.id))
                    }),
            )
            // Accepted property identities share the normal record counter.
            // Zero belongs only to a transient unsaved source.
            .chain(crate::depreciation::assets(self).map(|asset| asset.id).filter(|id| *id != 0))
            .chain(
                self.income
                    .iter()
                    .flat_map(|entry| {
                        crate::BusinessMileage::records(&entry.income).iter().map(|row| row.id)
                    })
                    .filter(|id| *id != 0),
            )
            // A farm's CCC loans carry record identities from the same counter
            // (a loan no Form 1099-A can name yet has none).
            .chain(
                self.income
                    .iter()
                    .flat_map(|v| crate::farm::ccc_lot_ids(&v.income))
                    .filter(|id| *id != 0),
            )
            .chain(
                self.income.iter().flat_map(|entry| crate::farm_specials::land_ids(&entry.income)),
            )
            .chain(self.income.iter().flat_map(|entry| {
                crate::method_change::records(&entry.income)
                    .into_iter()
                    .flat_map(|records| records.iter().map(|record| record.id))
            }))
            .collect();
        if ids
            .iter()
            .enumerate()
            .any(|(i, &id)| id <= 0 || id >= self.next_id || ids[..i].contains(&id))
        {
            return false;
        }
        if crate::savings_bonds::source_rule(&self.income).is_some()
            || crate::estate_trust::graph_rule(self).is_some()
            || crate::rental_energy::graph_issue(self).is_some()
        {
            return false;
        }
        for entry in &self.income {
            if let Err((failure, _)) = validate_income_issue(entry) {
                // Preserve the actual native range path through this same gate;
                // other stored validation failures retain their existing fallback.
                if failure.key == crate::k1_activity::ordinary::RANGE_KEY && failure.field.is_some()
                {
                    *issue = Some(failure);
                }
                return false;
            }
        }
        if self.dependents().iter().any(|v| validate_dependent(v).is_err()) {
            return false;
        }
        // A filer's 529-to-Roth transfers (Form 1099-Q box 4b) with the
        // earlier use on the IRA page: account age, seasoned balance and the
        // lifetime ceiling (ira.rs).
        let transfers = crate::ira::QtpTransfers::of(&self.income);
        let earlier = self.adjustments.as_ref().map_or([0, 0], |a| {
            [
                a.iras.taxpayer.qtp_roth_lifetime_prior,
                a.iras.spouse.as_ref().map_or(0, |f| f.qtp_roth_lifetime_prior),
            ]
        });
        if (0..2).any(|i| !crate::ira::valid_qtp_rollovers(transfers.owner(i), earlier[i])) {
            return false;
        }
        for (index, entry) in self.income.iter().enumerate() {
            if let FederalIncome::CasualtyLivingInsurance { data } = &entry.income {
                for prior in &self.income[..index] {
                    if let FederalIncome::CasualtyLivingInsurance { data: other } = &prior.income
                        && (other.event_reference == data.event_reference
                            || data.payments.iter().any(|payment| {
                                other.payments.iter().any(|earlier| {
                                    earlier.insurer == payment.insurer
                                        && earlier.payment_reference == payment.payment_reference
                                })
                            }))
                    {
                        return false;
                    }
                }
            }
        }
        if self.setup.as_ref().is_some_and(|s| matches!(s.status, FilingChoice::Separate { section179, .. } if !section179.valid())) {
            return false;
        }
        if self.people.as_ref().is_some_and(|v| {
            v.parent_tax.as_ref().is_some_and(|p| !p.valid())
                || !v.taxpayer.named()
                || v.spouse.as_ref().is_some_and(|p| !p.named())
                || !v.taxpayer.valid_dates()
                || v.spouse.as_ref().is_some_and(|p| !p.valid_dates())
        }) {
            return false;
        }
        if self.screening.as_ref().is_some_and(|v| {
            v.farm_averaging.as_ref().is_some_and(|a| !a.valid() || !a.sources_valid(self))
                || !crate::household_employment::valid(&v.household_employment)
                || v.section1231.as_ref().is_some_and(|h| !h.valid())
                || !v.qbi_history.valid()
                || !v.atnol.valid()
                || !v.nol.valid()
                || v.foreign_earned.iter().enumerate().any(|(i, c)| {
                    !c.housing.valid()
                        || !c.revocation.valid()
                        || !c.pay_valid()
                        || v.foreign_earned[..i].iter().any(|p| p.owner == c.owner)
                })
                || v.clergy.iter().enumerate().any(|(i, c)| {
                    !c.role.valid() || v.clergy[..i].iter().any(|p| p.owner == c.owner)
                })
                || !crate::able::valid_contributions(&v.able_contributions)
                || !crate::trump_account::valid_accounts(&v.trump_accounts)
                || v.public_safety.iter().any(|p| !p.valid())
                || !crate::extended_rules::valid_exercises(&v.iso_exercises)
                || !crate::extended_rules::valid_capital_history(&v.capital_history)
        }) {
            return false;
        }
        if !crate::health::plans_valid(self) {
            return false;
        }
        // Restored data is checked with the same amount invariants as accepted pages.
        if self.adjustments.as_ref().is_some_and(|v| {
            !v.health_marketplace.valid(self)
                || crate::health_employer::binding_rule(self, &v.health_employer_w2).is_some()
                || crate::health_employer::derived_rule(self).is_some()
                || v.pension_contributions.iter().any(|v| !v.valid())
                || !v.social_election.valid()
                || v.alimony_paid.iter().any(|p| !p.payment.valid())
                || v.moving.iter().any(|m| !m.record.valid())
                || !v.student_loan.forms.iter().all(crate::Form1098E::valid)
                || !amounts(&[
                    v.student_loan.student_loan_interest,
                    v.student_loan.employer_paid_interest,
                ])
                || !amounts(&[
                    v.educator_taxpayer(),
                    v.educator_spouse(),
                ])
                || v.educators.taxpayer.as_ref().is_some_and(|r| !r.valid())
                || v.educators.spouse.as_ref().is_some_and(|r| !r.valid())
                || v.employee_expenses.iter().any(|claim| !claim.valid())
                || v.entered_iras().is_some_and(|f| {
                    core::iter::once(&f.taxpayer)
                        .chain(f.spouse.iter()).enumerate()
                        .any(|(index, v)| {
                            !amounts(&[v.traditional, v.roth, v.nondeductible_election])
                                || v.nondeductible_election > v.traditional
                                || v.next_year_deposits.as_ref().is_some_and(|d| !d.valid())
                                || !(0..=crate::year_constants::QTP_ROTH_LIFETIME_LIMIT_CENTS)
                                    .contains(&v.qtp_roth_lifetime_prior)
                                || v.returned_next_year.iter().any(|r| !r.valid())
                                || v.excess.as_ref().is_some_and(|e| !e.valid(
                                    self.adjustments.as_ref().and_then(|a| a.ira_basis.iter().find(|b|
                                        usize::from(b.owner == Owner::Spouse) == index)).map(crate::IraBasis::form_5329_value_exact)))
                        })
                })
                || v.required_distributions.iter().any(|v| !v.valid())
                || v.roth_history.iter().any(|v| !v.valid())
                || v.ira_basis.iter().any(|b| !b.valid())
                // One QCD record per tax owner: taxpayer and spouse.
                || v.qualified_charity.len() > 2
                || v.qualified_charity.iter().any(|q| !q.valid())
                || !v.archer.valid()
                || v.hsa.iter().any(|h| !h.valid())
        }) || self.deductions.as_ref().is_some_and(|v| {
            !v.repayment.valid()
                || !v.valid_taxes()
                || crate::health::medical_expenses_issue(v.medical()).is_some()
                || crate::health::medical_source_amount(v.medical(), v.long_term_care()).is_err()
                || !amounts(&[
                    v.state_local_taxes(),
                    v.investment_property_taxes(),
                    v.cash_charity, v.fund_cash_charity, v.other_cash_charity,
                ])
                || v.mortgage_loans().iter().any(|loan| !loan.valid())
                || crate::mortgage_limit::graph_rule(v.mortgage_loans()).is_some()
                || v.annuity_losses.iter().any(|loss| !loss.valid())
                || v.personal_casualties.iter().any(|event| !event.valid())
                || !crate::PersonalCasualty::sources_representable(&v.personal_casualties)
                || crate::charity::page_problem(&v.property_gifts,&v.appraisals,&v.charity_carryovers,v.basis_election).is_some()
                || v.volunteer_expenses.iter().any(|expense| !expense.valid())
                || v.hosted_students.iter().any(|student| !student.valid())
                || v.whaling_captains.iter().any(|claim| !claim.valid())
                || v.whaling_captains.iter().enumerate().any(|(i, claim)| {
                    v.whaling_captains[..i]
                        .iter()
                        .any(|prior| prior.owner == claim.owner)
                })
                || v.hosted_students.iter().enumerate().any(|(i, student)| {
                    v.hosted_students[..i]
                        .iter()
                        .any(|prior| prior.label == student.label)
                })
                || v.annuity_losses.iter().enumerate().any(|(i, loss)| {
                    v.annuity_losses[..i]
                        .iter()
                        .any(|prior| prior.income_id == loss.income_id)
                })
                || v.vehicle_loans.iter().any(|v| {
                    v.label.trim().is_empty()
                        || !amounts(&[v.interest, v.business])
                        || v.business > v.interest
                })
        }) || self.credits.as_ref().is_some_and(|v| {
            // The people a student or a Marketplace dependent can be.
            let catalog = people_students(self);
            !crate::extended_rules::valid_credit(&v.foreign_tax)
                || (!joint(self.setup.as_ref().map_or(FederalStatus::Single, |s| s.filing_status()))
                    && matches!(&v.foreign_tax, ForeignTaxClaim::Deduction { taxes } if taxes.iter().any(|row| matches!(row.income, crate::ForeignTaxIncome::Earned { owner: Owner::Spouse }))))
                || v.tip_fica_carryforward
                    .as_ref()
                    .is_some_and(|history| !history.valid())
                || v.business_credits
                    .as_ref()
                    .is_some_and(|history| !history.valid() || history.rule().is_some())
                || v.minimum_tax.as_ref().is_some_and(|v| !v.valid() || self.setup.as_ref().is_some_and(|s| v.rule(s.filing_status()).is_some()))
                || v.mortgage_subsidies.iter().enumerate().any(|(i, entry)| {
                    !entry.valid()
                        || v.mortgage_subsidies[..i].iter().any(|prior| {
                            prior.label == entry.label
                                || entry.home_sale_income_id().is_some()
                                    && entry.home_sale_income_id() == prior.home_sale_income_id()
                        })
                })
                || v.mortgage_credit.as_ref().is_some_and(|credit| {
                    !amounts(&[credit.carry_three_years_prior, credit.carry_two_years_prior, credit.carry_prior_year])
                        || credit.current.as_ref().is_some_and(|current| {
                            current.issuer.trim().is_empty()
                                || current.number.trim().is_empty()
                                || !valid_date(current.issue_date)
                                || current.issue_date > 20261231
                                || !current.interest.valid()
                                || !(1000..=5000).contains(&current.rate_hundredths_percent)
                                || !(1..=10000).contains(&current.ownership_basis_points)
                                || match &current.history {
                                    crate::MortgageCertificateHistory::ReissuedBefore2026 {
                                        facts,
                                    } => {
                                        current.issue_date > 20251231
                                            || facts.refinanced_on > 20251231
                                            || !facts.valid_for(current.rate_hundredths_percent, false)
                                            || current.interest.certified_debt().is_some_and(|debt| debt != facts.reissued_certified_debt)
                                    }
                                    crate::MortgageCertificateHistory::ReissuedDuring2026SameRate {
                                        facts,
                                        original_period_interest,
                                    } => {
                                        current.issue_date < 20260101
                                            || facts.refinanced_on < 20260101
                                            || !facts.valid_for(current.rate_hundredths_percent, true)
                                            || current.interest.certified_debt().is_some_and(|debt| debt != facts.reissued_certified_debt)
                                            || !original_period_interest.valid()
                                            || current.interest.certified_interest()
                                                > 100_000_000_000
                                                    - original_period_interest.certified_interest()
                                    }
                                    crate::MortgageCertificateHistory::ReissuedDuring2026DifferentRates {
                                        facts,
                                        original_period_interest,
                                    } => {
                                        current.issue_date < 20260101
                                            || facts.refinanced_on < 20260101
                                            || !facts.valid_for(current.rate_hundredths_percent, false)
                                            || current.interest.certified_debt().is_some_and(|debt| debt != facts.reissued_certified_debt)
                                            || current.rate_hundredths_percent
                                                == facts.original_rate_hundredths_percent
                                            || !original_period_interest.valid()
                                            || current.interest.certified_interest()
                                                > 100_000_000_000
                                                    - original_period_interest.certified_interest()
                                    }
                                    _ => false,
                                }
                        })
                })
                || v.dc_homebuyer_carry.is_some_and(|carry| !amounts(&[carry]))
                || v.residential_energy_carry
                    .is_some_and(|carry| !amounts(&[carry]))
                || v.personal_refueling.iter().any(|property| {
                    property.label.trim().is_empty()
                        || !valid_date(property.placed_in_service)
                        || !amounts(&[property.cost])
                        // Identifier format: a Census tract GEOID has exactly eleven digits.
                        || property.census_geoid.len() != 11
                        || !property
                            .census_geoid
                            .bytes()
                            .all(|digit| digit.is_ascii_digit())
                })
                || v.clean_vehicles
                    .as_ref()
                    .is_some_and(|claim| !crate::clean_vehicle::valid(claim) || crate::clean_vehicle::source_issue(self, claim).is_some())
                || v.legacy_ev_passive_allowed
                    .is_some_and(|amount| !amounts(&[amount]))
                || !crate::adoption::valid(&v.adoptions, &v.adoption_carry)
                || !crate::marketplace::valid_with_issue(&v.marketplace, self, issue)
                || v.exempt_pensions.iter().any(|b| {
                    b.label.trim().is_empty() || !amounts(&[b.amount])
                })
                || !crate::tax_credit_bonds::valid(&v.tax_credit_bonds)
                || !amounts(&[v.care_expenses()])
                || !v.care.valid(self)
                || v.saver.as_ref().is_some_and(|f| {
                    !amounts(&[
                        f.taxpayer_contributions,
                        f.spouse_contributions,
                        f.taxpayer_able,
                        f.spouse_able,
                    ])
                        || f.distributions.iter().any(|d| !amounts(&[d.amount]))
                })
                || v.education.iter().any(|e| {
                    !amounts(&e.expenses.components())
                        || !catalog.iter().any(|s| s.id == e.student)
                })
                || v.education_recapture.as_ref().is_some_and(|entry| !entry.valid())
        }) || self.payments.as_ref().is_some_and(|v| {
            v.estimated.is_some_and(|amount| amount < 0) || v.extension < 0
                || v.credit_applied_next_year < 0
                || (v.credit_applied_next_year > 0 && v.credit_recipient.is_none())
                || v.home_kerosene.as_ref().is_some_and(|fuel| !fuel.valid())
                || v.estimated_payments.iter().any(|p| !p.valid())
                || v.projection_issue().is_some_and(|failure| {
                    *issue = Some(failure.in_field("payments"));
                    true
                })
                || v.prior_year.as_ref().is_some_and(|p| !p.valid())
                || v.withholding_periods.as_ref().is_some_and(|p| !p.valid())
                || v.annualized_income.as_ref().is_some_and(|p| !p.valid())
                || v.waiver.as_ref().is_some_and(|w| !w.valid())
        }) {
            return false;
        }
        crate::tax_credit_bonds::source_rule(self).is_none()
    }
}
// At most 100 expense records, each labelled where it must be and within range.
pub(crate) fn expenses_valid(expenses: &[crate::FederalBusinessExpense]) -> bool {
    expenses.len() <= 100
        && expenses.iter().all(|e| {
            (match &e.category {
                crate::BusinessExpenseCategory::Other { label } => !label.trim().is_empty(),
                _ => true,
            }) && amounts(&[e.amount])
                && match e.treatment {
                    crate::BusinessExpenseKind::DeMinimis { largest_cost, .. } => {
                        largest_cost > 0 && amounts(&[largest_cost])
                    }
                    _ => true,
                }
        })
}
fn amounts(v: &[i64]) -> bool {
    v.iter().all(|n| (0..=MAX).contains(n))
}
pub(crate) fn validate_dependent(d: &FederalDependent) -> Result<(), (&'static str, &'static str)> {
    if !valid_birth(d.birth_date) {
        return Err((
            "ISSUE_FEDERAL_RULES_ENTER_A_VALID_BIRTH_DATE_ON_E3FCDFD3",
            crate::fixture_english!("Enter a valid birth date on or before December 31, 2026."),
        ));
    }
    if d.days_in_home() > 365 || !amounts(&[d.care_expenses(), d.gross_income()]) {
        return Err((
            "DEPENDENT_NAME_DAYS_OR_AMOUNTS",
            crate::fixture_english!("Review this person's name, residency days and amounts."),
        ));
    }
    if let DependentResidency::Days { days } = d.residency
        && d.birth_date / 10000 == 2026
        && days as i32 > crate::dates::days_between(d.birth_date, 20261231) + 1
    {
        return Err((
            "ISSUE_FEDERAL_RULES_RESIDENCE_DAYS_CANNOT_EXCEED_DAYS_ALIVE_1A7BB934",
            crate::fixture_english!(
                "Residence days cannot exceed days alive in 2026. Use the qualifying residency exception when the newborn rule applies."
            ),
        ));
    }
    if d.has(crate::PersonFacts::ADOPTED_US_CITIZEN_PARENT)
        && d.relationship != crate::Relationship::Child
    {
        return Err((
            "MEDICAL_ADOPTED_CHILD_RELATIONSHIP",
            crate::fixture_english!("Review the adopted-child medical exception and relationship."),
        ));
    }
    if d.has(crate::PersonFacts::MEDICAL_SEPARATED_PARENTS)
        && (d.relationship != crate::Relationship::Child
            || d.own_support_over_half()
            || d.multiple_support())
    {
        return Err((
            "MEDICAL_PARENT_SUPPORT_FACTS_CONFLICT",
            crate::fixture_english!(
                "Review the separated-parent medical relationship and support facts."
            ),
        ));
    }
    if d.own_support_over_half() && d.your_support_over_half() {
        return Err((
            "ISSUE_FEDERAL_RULES_BOTH_YOU_AND_THIS_PERSON_CANNOT_56C06D31",
            crate::fixture_english!(
                "Both you and this person cannot each provide more than half the same total support."
            ),
        ));
    }
    Ok(())
}
pub(crate) fn validate_income(e: &FederalIncomeEntry) -> Result<(), (&'static str, &'static str)> {
    validate_income_issue(e).map_err(|(issue, message)| (issue.key, message))
}
pub(crate) fn validate_income_amount(
    income: &FederalIncome,
) -> Result<(), (&'static str, &'static str)> {
    validate_income_amount_issue(income).map_err(|(issue, message)| (issue.key, message))
}
pub(crate) fn validate_income_issue(
    e: &FederalIncomeEntry,
) -> Result<(), (crate::validation::ValidationIssue, &'static str)> {
    if let Some(issue) = crate::method_change::farm_link_issue(&e.income) {
        return Err((
            issue,
            crate::fixture_english!(
                "Select this farm's actual accepted accounting-change source and its consent evidence."
            ),
        ));
    }
    if crate::investment_statements::unresolved_contingent(&e.income) {
        return Err((
            crate::validation::ValidationIssue::new("ISSUE_DEBT_CONTINGENT_INCOME"),
            crate::fixture_english!(
                "A contingent-payment instrument needs its comparable-yield and projected-payment computation."
            ),
        ));
    }
    validate_income_amount_issue(&e.income)
}

pub(crate) fn validate_income_amount_issue(
    income: &FederalIncome,
) -> Result<(), (crate::validation::ValidationIssue, &'static str)> {
    let mut native_issue = None;
    validate_income_amount_details(income, &mut native_issue).map_err(|(key, message)| {
        let mut issue =
            native_issue.unwrap_or_else(|| crate::validation::ValidationIssue::new(key));
        issue.key = key;
        (issue, message)
    })
}
// Preserve legacy localized/fixture diagnostics while carrying metadata from
// the same native amount pass. This helper is the sole predicate owner.
fn validate_income_amount_details(
    income: &FederalIncome,
    native_issue: &mut Option<crate::validation::ValidationIssue>,
) -> Result<(), (&'static str, &'static str)> {
    if let Some(issue) = crate::k1_activity::income_issue(income) {
        let key = issue.key;
        *native_issue = Some(issue);
        return Err((
            key,
            crate::fixture_english!(if key == crate::k1_activity::ordinary::RANGE_KEY {
                "Review the document amounts; they must be within the supported input range."
            } else {
                "Reconcile this K-1's actual component source records."
            }),
        ));
    }
    let valid = match income {
        // The complete new-source rule above owns this source's validation once.
        FederalIncome::PartnershipActivities { .. } | FederalIncome::ScorpActivities { .. } => true,
        FederalIncome::Royalty { data } => data.valid(),
        FederalIncome::ChildElection { data } => data.valid(),
        FederalIncome::Cooperative { data } => {
            *native_issue = data.issue();
            native_issue.is_none()
        }
        FederalIncome::Partnership { data } => {
            *native_issue = data.validation_issue(
                "ISSUE_FEDERAL_RULES_REVIEW_THE_DOCUMENT_AMOUNTS__THEY_MUST_17724C26",
            );
            native_issue.is_none()
        }
        FederalIncome::Scorp { data } => data.valid(),
        FederalIncome::EstateTrustPortfolio { data } => data.valid(),
        FederalIncome::NonbusinessProperty { kind, receipts, expenses, .. } => {
            amounts(&[*receipts, *expenses])
                && match kind {
                    NonbusinessPropertyKind::PersonalRental {
                        basis,
                        depreciable_basis,
                        assets,
                        history,
                    } => {
                        (0..=100000000000).contains(basis)
                            && (0..=*basis).contains(depreciable_basis)
                            && amounts(&[history.balance(false), history.balance(true)])
                            && assets.len() <= 100
                            && assets.iter().all(crate::BusinessAsset::valid)
                            && assets.iter().map(|a| a.cost).sum::<i64>() <= *depreciable_basis
                    }
                }
        }
        FederalIncome::SmallBusinessStock { data } => data.valid(),
        FederalIncome::QualifiedSmallBusinessSale { data } => data.valid(),
        FederalIncome::TaxRefund { amount, history, withholding } => {
            amounts(&[*amount, *withholding]) && history.valid()
        }
        FederalIncome::WorthlessSecurity { data } => {
            amounts(&[data.basis]) && data.acquisition.valid()
        }
        FederalIncome::NonbusinessBadDebt { data } => data.source.valid() && data.rule().is_none(),
        FederalIncome::HomeSale { data } => data.valid(),
        FederalIncome::ReturnOfCapital { amount, basis, property, .. } => {
            crate::CapitalReturn1099Div::valid_amounts(*amount, *basis, property)
        }
        FederalIncome::UndistributedGain { data: v } => {
            amounts(&[v.gain, v.unrecaptured, v.small_business, v.collectibles, v.tax_paid])
                && v.unrecaptured + v.small_business + v.collectibles <= v.gain
                && v.tax_paid <= v.gain
                && (v.small_business == 0 || v.section_1202_exclusion.is_some())
        }
        FederalIncome::OpportunityFund { data } => data.valid(),
        FederalIncome::OpportunityFundDeferral { data } => data.valid(),
        FederalIncome::Able { data } => data.valid(),
        FederalIncome::TrumpDeath { data } => data.valid(),
        FederalIncome::TrumpAbleRollover { data } => data.valid(),
        FederalIncome::LtcBenefits { data } => data.valid(),
        FederalIncome::LtcInsured { data } => data.valid(),
        FederalIncome::MedicalDistribution { data } => data.valid(),
        FederalIncome::HobbySales { data } => data.valid(),
        FederalIncome::PersonalDebt { data } => data.valid(),
        FederalIncome::PropertyAcquisition { data } => data.valid(),
        FederalIncome::HealthLoanAssistance { data } => data.valid(),
        FederalIncome::WildfireRelief { data } => data.valid(),
        FederalIncome::DisasterRelief { data } => data.valid(),
        FederalIncome::CasualtyLivingInsurance { data } => data.valid(),
        FederalIncome::DisasterMitigation { data } => data.valid(),
        FederalIncome::OtherIncome { data } => data.valid(),
        FederalIncome::Nec1099 { data } => data.valid(),
        FederalIncome::Misc1099 { data } => data.valid(),
        FederalIncome::K1099 { data } => data.valid(),
        FederalIncome::Scholarship { data } => data.valid(),
        FederalIncome::JuryDuty { data } => data.valid(),
        FederalIncome::Alimony { data } => data.valid(),
        FederalIncome::SavingsBonds { data } => data.valid(),
        FederalIncome::Section1256 { data } => data.valid(),
        FederalIncome::EducationDistribution { data } => data.valid(),
        FederalIncome::EducationAccountExpenses { data } => data.valid(),
        FederalIncome::ForeignEmployment { data: v } => amounts(&[v.wages]),
        FederalIncome::EmployeeWages { data } => data.valid(),
        FederalIncome::Rental { data: v } => crate::extended_rules::rental_source_valid(v),
        FederalIncome::FarmRental { data } => data.valid(),
        FederalIncome::Wage { data: w } => {
            amounts(&[
                w.wages,
                w.withholding,
                w.social_wages,
                w.social_tips,
                w.social_tax,
                w.medicare_wages,
                w.medicare_tax,
                w.medicaid_waiver,
            ]) && w.deferred_pension + w.inmate_pay + w.medicaid_waiver <= w.wages
                && w.payroll.valid()
                && (0..=w.wages).contains(&w.disability.amount())
                && (0..=w.wages).contains(&w.abroad)
                && w.employee_tips.as_ref().is_none_or(|v| v.valid())
                && w.uncollected_tax.as_ref().is_none_or(|v| v.valid())
                && w.work_deductions.tips_valid()
                && amounts(&[w.work_deductions.overtime()])
        }
        FederalIncome::Interest { data: v } => {
            if v.private_activity > v.exempt {
                return Err((
                    "INT_PRIVATE_ACTIVITY_ABOVE_EXEMPT",
                    crate::fixture_english!(
                        "Private-activity interest must be included in exempt income."
                    ),
                ));
            }
            if let Some(key) = crate::investment_statements::int_rule(v) {
                return Err((
                    key,
                    crate::fixture_english!(
                        "Investment ownership or reporting facts are inconsistent."
                    ),
                ));
            }
            v.private_activity <= v.exempt
                && amounts(&[
                    v.taxable,
                    v.us_obligations,
                    v.exempt,
                    v.private_activity,
                    v.withholding,
                    v.early_penalty,
                    v.bond_premium,
                    v.treasury_bond_premium,
                    v.tax_exempt_bond_premium,
                    v.accrued_interest,
                    v.foreign_tax,
                    v.investment_expenses,
                    v.market_discount,
                ])
        }
        FederalIncome::Oid { data: v } => {
            if v.private_activity > v.exempt {
                return Err((
                    "OID_PRIVATE_ACTIVITY_ABOVE_EXEMPT",
                    crate::fixture_english!(
                        "Private-activity interest must be included in exempt income."
                    ),
                ));
            }
            if let Some(key) = crate::investment_statements::oid_rule(v) {
                return Err((
                    key,
                    crate::fixture_english!(
                        "Investment ownership or reporting facts are inconsistent."
                    ),
                ));
            }
            v.private_activity <= v.exempt
                && (-MAX..=MAX).contains(&v.treasury_oid)
                && amounts(&[
                    v.oid,
                    v.other_periodic_interest,
                    v.early_penalty,
                    v.withholding,
                    v.market_discount,
                    v.acquisition_premium,
                    v.exempt,
                    v.bond_premium,
                    v.private_activity,
                    v.investment_expenses,
                    v.tax_exempt_bond_premium,
                ])
        }
        FederalIncome::Dividend { data: v } => {
            if v.collectible_distributions + v.unrecaptured_distributions > v.capital_distributions
            {
                return Err((
                    "ISSUE_FEDERAL_RULES_SECTION_1250_AND_COLLECTIBLE_COMPONENTS_IN_AF75329A",
                    crate::fixture_english!(
                        "Section 1250 and collectible components in boxes 2b and 2d cannot exceed total capital gain distributions in box 2a."
                    ),
                ));
            }
            if v.qualified + v.section199a.amount() > v.ordinary {
                return Err((
                    "ISSUE_FEDERAL_RULES_QUALIFIED_AND_SECTION_199A_DIVIDENDS_MUST_94CFB1A7",
                    crate::fixture_english!(
                        "Qualified and section 199A dividends must be separate parts of ordinary dividends; their sum cannot exceed box 1a."
                    ),
                ));
            }
            if v.private_activity_dividends > v.exempt_dividends {
                return Err((
                    "ISSUE_FEDERAL_RULES_SPECIFIED_PRIVATE_ACTIVITY_BOND_INTEREST_DIVIDENDS_IN_AAA9238B",
                    crate::fixture_english!(
                        "Specified private-activity bond interest dividends in box 13 cannot exceed exempt-interest dividends in box 12."
                    ),
                ));
            }
            if v.section_1202_gain > v.capital_distributions
                || v.section_1202_gain != 0 && v.section_1202_exclusion.is_none()
            {
                return Err((
                    if v.section_1202_gain > v.capital_distributions {
                        "DIV_SECTION_1202_ABOVE_2A"
                    } else {
                        "DIV_SECTION_1202_NEEDS_EXCLUSION"
                    },
                    crate::fixture_english!(
                        "Box 2c section 1202 gain is part of box 2a, and its exclusion must be chosen."
                    ),
                ));
            }
            if v.section_897_ordinary > v.ordinary {
                return Err((
                    "DIV_897_ORDINARY_ABOVE_BOX",
                    crate::fixture_english!(
                        "Box 2e section 897 ordinary dividends cannot exceed box 1a."
                    ),
                ));
            }
            if v.section_897_capital > v.capital_distributions {
                return Err((
                    "DIV_897_CAPITAL_ABOVE_BOX",
                    crate::fixture_english!(
                        "Box 2f section 897 capital gain cannot exceed box 2a."
                    ),
                ));
            }
            if let Some(key) = crate::investment_statements::div_rule(v) {
                return Err((
                    key,
                    crate::fixture_english!(
                        "Investment ownership or reporting facts are inconsistent."
                    ),
                ));
            }
            amounts(&[
                v.ordinary,
                v.qualified,
                v.section199a.amount(),
                v.capital_distributions,
                v.collectible_distributions,
                v.unrecaptured_distributions,
                v.section_1202_gain,
                v.withholding,
                v.exempt_dividends,
                v.private_activity_dividends,
                v.foreign_tax,
                v.section_897_ordinary,
                v.section_897_capital,
            ])
        }
        FederalIncome::NuaSale { data } => data.valid(),
        FederalIncome::EmployeeStockSale { data } => data.valid(),
        FederalIncome::EsppSale { data } => data.valid(),
        FederalIncome::IsoSale { data } => data.valid(),
        FederalIncome::Sale { data: v } => {
            validate_sale(v)?;
            true
        }
        FederalIncome::Roth { data } => data.valid(),
        FederalIncome::InheritedIra { data } => data.valid(),
        FederalIncome::Retirement { data: v } => {
            if let Some(key) = v.care_charge_rule() {
                return Err((
                    key,
                    crate::fixture_english!(
                        "A qualified codeW care charge needs its actual nontaxable source and reported investment reduction."
                    ),
                ));
            }
            if matches!(v.taxable, crate::RetirementTaxable::Payer { amount } if amount > v.gross) {
                return Err((
                    "ISSUE_FEDERAL_RULES_TAXABLE_RETIREMENT_INCOME_CANNOT_EXCEED_ITS_D4BD4F9F",
                    crate::fixture_english!(
                        "Taxable retirement income cannot exceed its gross distribution in this supported path."
                    ),
                ));
            }
            amounts(&[v.gross, v.withholding])
                && (0..=v.gross).contains(&v.disability.amount())
                && v.disability_wages.valid()
                && (v.disability_wages == crate::DisabilityWages::None
                    || v.reports_disability_wages())
                && v.disaster.valid(v.gross)
                && (0..=v.gross).contains(&v.box_10)
                && match v.ordinary_distribution {
                    RetirementTreatment::Corrective { excess_deferral } => {
                        (0..=100000000000).contains(&excess_deferral)
                    }
                    _ => true,
                }
                && match v.taxable {
                    crate::RetirementTaxable::Payer { amount } => amounts(&[amount]),
                    crate::RetirementTaxable::CivilServiceDeath {
                        data: crate::SurvivorLumpSum { cost, recovered, .. },
                    } => amounts(&[cost, recovered]) && recovered <= cost,
                    crate::RetirementTaxable::PropertyProceeds { ref data } => data.valid(),
                    crate::RetirementTaxable::Inherited { account, payer } => {
                        account.is_none_or(|id| id > 0)
                            && amounts(&[payer])
                            && payer <= v.gross
                            && v.kind == RetirementKind::Inherited
                    }
                    crate::RetirementTaxable::LegacyAnnuity { ref data } => data.valid(v.gross),
                    crate::RetirementTaxable::IraBasis => true,
                    crate::RetirementTaxable::FullDischarge {
                        data: crate::ContractDischarge { investment, .. },
                    } => amounts(&[investment]),
                    crate::RetirementTaxable::QualifiedWithdrawal {
                        data: crate::PlanDistribution { value, investment, .. },
                    } => amounts(&[value, investment]) && value > 0 && v.gross <= value,
                    crate::RetirementTaxable::DeferredWithdrawal { ref data } => {
                        data.value >= 0
                            && data.investment >= 0
                            && v.gross <= data.value
                            && data.related.iter().all(|v| v.value >= 0 && v.investment >= 0)
                    }
                    crate::RetirementTaxable::GeneralAnnuity { data } => data.valid(v.gross),
                    crate::RetirementTaxable::VariableAnnuity { data } => data.valid(),
                    crate::RetirementTaxable::Railroad {
                        contributory,
                        box_5,
                        box_6,
                        ref basis,
                        ref repayments,
                        ..
                    } => {
                        (0..=v.gross).contains(&contributory)
                            && amounts(&[box_5, box_6])
                            && contributory + box_5 + box_6 == v.gross
                            && basis.as_ref().is_none_or(|b| b.valid())
                            && repayments.len() <= 100
                            && repayments.iter().all(|p| {
                                (1900..=2025).contains(&p.received_year) && amounts(&[p.amount])
                            })
                    }
                    crate::RetirementTaxable::ChildAnnuity { ref data } => data.valid(v.gross),
                    crate::RetirementTaxable::Simplified { ref data } => data.valid(),
                }
                && match &v.ordinary_distribution {
                    RetirementTreatment::Rollover { amount, .. } => {
                        let ceiling = match &v.taxable {
                            crate::RetirementTaxable::PropertyProceeds { data } => data.proceeds,
                            _ => v.gross,
                        };
                        (0..=ceiling).contains(amount)
                    }
                    RetirementTreatment::Conversion { amount, .. } => {
                        (0..=v.gross).contains(amount)
                    }
                    RetirementTreatment::Exception { distributed, facts, .. } => {
                        facts.valid(*distributed, v.gross)
                    }
                    // Form 4972 (lump_sum.rs): a qualified-plan record with the payer's box 2a
                    // and exactly code 7A (the filer's own plan) or 4A (a decedent's).
                    RetirementTreatment::LumpSum { data } => {
                        let a = crate::DistributionCodes::CODE_A.0;
                        v.kind == RetirementKind::Pension
                            && matches!(v.taxable, crate::RetirementTaxable::Payer { amount }
                                if data.valid(amount))
                            && match data.participant {
                                crate::Form4972Participant::Own { .. } => {
                                    v.box7 == crate::DistributionCodes::CODE_7.0 | a
                                }
                                crate::Form4972Participant::Decedent { .. } => {
                                    v.box7 == crate::DistributionCodes::CODE_4.0 | a
                                }
                            }
                    }
                    _ => true,
                }
        }
        FederalIncome::SocialSecurity { data: v } => {
            (-100_000_000_000..=100_000_000_000).contains(&v.benefits) && amounts(&[v.withholding])
        }
        FederalIncome::Unemployment { data: v } => {
            amounts(&[
                v.amount,
                v.withholding,
                v.taxable_grants,
                v.agriculture_payment,
                v.rtaa,
                v.market_gain,
                v.family_leave,
            ]) && v.repayments.len() <= 100
                && v.repayments
                    .iter()
                    .all(|p| (1900..=2026).contains(&p.received_year) && amounts(&[p.amount]))
        }
        FederalIncome::Gambling { data: v } => amounts(&[v.winnings, v.losses, v.withholding]),
        FederalIncome::Business { data: v } => {
            v.activity.valid()
                && v.at_risk
                    .issue_for_method(
                        &if matches!(v.activity, crate::BusinessActivity::Farming { .. }) {
                            crate::RiskEffectiveCategory::Farming
                        } else {
                            crate::RiskEffectiveCategory::OtherTradeBusiness
                        },
                        true,
                    )
                    .is_none()
                && (0..=100000000000).contains(&v.notary_profit)
                && v.notary_gross
                    .is_none_or(|gross| (v.notary_profit..=100000000000).contains(&gross))
                && v.income_source.valid()
                && v.payroll.valid()
                && v.inventory.valid()
                && v.other_income.len() <= 20
                && v.other_income.iter().all(|i| {
                    !i.description.trim().is_empty() && (1..=100000000000).contains(&i.amount)
                })
                && v.business_code.is_none_or(|c| (100000..=999999).contains(&c))
                && (v.ein.is_empty()
                    || (v.ein.len() == 10
                        && v.ein.as_bytes()[2] == b'-'
                        && v.ein.bytes().enumerate().all(|(i, b)| i == 2 || b.is_ascii_digit())))
                && v.de_minimis.as_ref().is_none_or(crate::DeMinimisElection::valid)
                && v.leased_vehicles.len() <= 100
                && v.leased_vehicles.iter().all(crate::BusinessLeasedVehicle::valid)
                && (!matches!(v.activity, crate::BusinessActivity::Farming { .. })
                    || v.leased_vehicles.is_empty())
                && v.depletion.as_ref().is_none_or(crate::BusinessDepletion::valid)
                && v.startup.valid()
                && crate::method_change::valid(&v.method_changes)
                && v.intangibles.len() <= 100
                && v.intangibles.iter().all(crate::BusinessIntangible::valid)
                && v.timber.iter().all(crate::BusinessTimberCost::valid)
                && v.other_amortization.iter().all(crate::OtherAmortizableCost::valid)
                && (v.timber.is_empty()
                    || (matches!(v.activity, crate::BusinessActivity::Ordinary { .. })
                        && v.source == crate::BusinessSource::UnitedStates))
                && v.health_insurance.valid()
                && v.retirement.valid()
                && v.assets.len() <= 100
                && v.assets.iter().all(crate::BusinessAsset::valid)
                && v.vehicles.len() <= 100
                && v.vehicles.iter().all(|vehicle| vehicle.valid())
                && expenses_valid(&v.expenses)
                && v.tips.as_ref().is_none_or(|tips| amounts(&[tips.amount]))
                && v.overtime.as_ref().is_none_or(|overtime| amounts(&[overtime.amount]))
                && v.fuel_tax_credit.as_ref().is_none_or(|claim| claim.valid())
                && v.employer_tip_fica_credit
                    .as_ref()
                    .is_none_or(crate::EmployerTipFicaCredit::valid)
                && v.work_opportunity_credit
                    .as_ref()
                    .is_none_or(crate::WorkOpportunityCredit::valid)
                && v.retirement_plan_credit.as_ref().is_none_or(crate::RetirementPlanCredit::valid)
                && v.small_employer_health_credit
                    .as_ref()
                    .is_none_or(crate::SmallEmployerHealthCredit::valid)
                && v.paid_leave_credit.as_ref().is_none_or(crate::PaidLeaveCredit::valid)
                && v.cash_fuel_tax_recovery
                    .as_ref()
                    .is_none_or(|recovery| recovery.valid() && v.cash_accounting())
                && v.withholding >= 0
                && amounts(&[v.withholding])
                && {
                    if (!v.timber.is_empty() || !v.other_amortization.is_empty())
                        && (v.checked_amortization_cents().is_none()
                            || [false, true].into_iter().any(|mid_quarter| {
                                v.checked_operating_cost_before_supplies(mid_quarter).is_none()
                            }))
                    {
                        let (key, field) = if v.other_amortization.is_empty() {
                            ("TIMBER_TOTAL_UNREPRESENTABLE", "timber")
                        } else {
                            ("AMORTIZATION_TOTAL_UNREPRESENTABLE", "other_amortization")
                        };
                        *native_issue = Some(
                            crate::validation::ValidationIssue::new(key)
                                .at_field(field)
                                .in_field("more"),
                        );
                        return Err((
                            key,
                            crate::fixture_english!(
                                "Correct the original amortization sources before the combined native amount can be calculated."
                            ),
                        ));
                    }
                    true
                }
        }
    };
    if valid {
        Ok(())
    } else {
        Err((
            "ISSUE_FEDERAL_RULES_REVIEW_THE_DOCUMENT_AMOUNTS__THEY_MUST_17724C26",
            crate::fixture_english!(
                "Review the document amounts; they must be within the supported input range."
            ),
        ))
    }
}

// Form 8941 line 15 (code BA) and Form 8994 line 2 (code BB): the owner's
// K-1 (1065) box 15 and K-1 (1120-S) box 13 credits of one code, whole
// dollars. Each K-1 amount also reaches Form 3800 Part III on its own entry.
fn k1_credit_code(d: &FederalDraft, owner: crate::Owner, code: crate::K1CreditCode) -> i64 {
    dollars(
        d.income
            .iter()
            .filter(|entry| entry.owner == owner)
            .filter_map(|entry| match &entry.income {
                FederalIncome::Partnership { data } => Some(&data.credits),
                FederalIncome::Scorp { data } => Some(&data.credits),
                _ => None,
            })
            .flatten()
            .filter(|credit| credit.code == code)
            .map(|credit| credit.amount)
            .sum(),
    )
}

fn expense_elections(
    r: &mut FederalResult,
    expenses: &[crate::FederalBusinessExpense],
    context: &crate::IssueContext,
    #[cfg(test)] source: &str,
    prefix: &str,
) {
    for (index, expense) in expenses.iter().enumerate() {
        if let crate::BusinessExpenseKind::DeMinimis {
            largest_cost,
            financial_statement,
            eligible,
        } = expense.treatment
        {
            let ceiling = if financial_statement { 500_000 } else { 250_000 };
            // An ineligible expense is left out before the rules run.
            crate::require_localized!(
                r,
                eligible && largest_cost <= ceiling,
                context,
                source,
                "ISSUE_DE_MINIMIS_ELECTION_REQUIRES_CONFIRMED_ELIGIBLE_BOOK_EXPENSING_THE_20E65A9C",
                "De minimis election requires confirmed eligible book expensing, the annual election for all qualifying purchases, and invoice/item costs at most $2,500 without an applicable financial statement or $5,000 with one. Reclassify ineligible purchases under their ordinary rules; an over-limit item is not a partially deductible safe-harbor purchase.",
            );
            crate::require_localized!(
                r,
                expenses.iter().all(|other| match other.treatment {
                    crate::BusinessExpenseKind::DeMinimis {
                        financial_statement: other_statement,
                        ..
                    } => other_statement == financial_statement,
                    _ => true,
                }),
                context,
                source,
                "ISSUE_USE_CONSISTENT_APPLICABLE_FINANCIAL_STATEMENT_FACTS_FOR_THIS_ACTIVI_5F5D61F3",
                "Use consistent applicable-financial-statement facts for this activity's de minimis purchases.",
            );
            line_cents(
                r,
                &alloc::format!("{prefix}_expense_{index}_de_minimis"),
                expense.amount,
                &["income.expenses"],
                "https://www.irs.gov/businesses/small-businesses-self-employed/tangible-property-final-regulations",
                msg!("EXPLAIN_N_EXPENSE_N_DE_MINIMIS_2"),
            );
        }
    }
}

// What the Form 8814 elections report on this return, in whole dollars
// (child_election.rs): the amounts already in the dividend and capital
// totals are not repeated here.
#[derive(Default)]
pub(crate) struct ChildTotals {
    // Same-invocation source parents, in native whole dollars. The totals
    // below remain unchanged; these projections never rerun Form8814.
    pub(crate) qualified_by_owner: [i64; 2],
    pub(crate) other_by_owner: [i64; 2],
    pub(crate) investment_by_owner: [i64; 2],
    pub(crate) tax_by_owner: [i64; 2],
    // Line 9, the qualified dividends the elections report.
    pub(crate) qualified: i64,
    // Line 10, the capital gain distributions the elections report.
    pub(crate) distributions: i64,
    // Line 12: Schedule 1 line 8z.
    pub(crate) other: i64,
    // Line 12 less the Alaska Permanent Fund share: Form 8960 line 7, Form
    // 4952 investment income and Pub 596 Worksheet 1 line 4.
    pub(crate) investment: i64,
    // Line 1b, the children's tax-exempt interest (Pub 596 Worksheet 1 line 2).
    pub(crate) exempt: i64,
    // Line 15: Form 1040 line 16.
    pub(crate) tax: i64,
    // Form 8962 household income (i8962 line 2b, "Form 8814"): line 1b plus the lesser of
    // line 4 and line 5, for each election over the $1,350 not taxed.
    pub(crate) household_income: i64,
}

